window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["11589950"]={"book":{"id":11589950,"title":"沃顿商学院最受欢迎的谈判课","author":"[美] 斯图尔特·戴蒙德","translator":"杨晓红","publisher":"中信出版社","pubdate":"2012-8","isbn":"9787508634760","tags":["谈判","沟通","沃顿商学院","管理","心理学","经营管理","学习","经济"],"memCount":13},"np":1,"pb":[15],"idx":[{"i":8595,"t":"谈判中如何通过不等价交易获得更多？","l":"TF3-3","c":"莫念","g":1,"p":1},{"i":8051,"t":"TF2-1过级","l":"TF2-1","c":"超先森","g":1,"p":1},{"i":5452,"t":"如何提高谈判能力，争取更多权益","l":"TF2-3","c":"黄茂林","g":1,"p":1},{"i":5244,"t":"循序渐进地沟通法则","l":"TF2-1","c":"无敌","g":1,"p":1},{"i":5205,"t":"如何应用准则提高谈判能力","l":"TF1-2","c":"黄茂林","g":1,"p":1},{"i":4465,"t":"用不等价交易实现你的谈判目标","l":"TF1-1","c":"安妮","g":0,"p":1},{"i":3873,"t":"换种思路谈判","l":"TF2-4","c":"哆啦","g":1,"p":1},{"i":3507,"t":"有技巧的使用“识别”、“倾听”、“化解”三个步骤","l":"TF2-1","c":"小玲","g":1,"p":1},{"i":3105,"t":"循序渐进的谈判法则","l":"TF3-1","c":"张馨月","g":1,"p":1},{"i":2116,"t":"化敌为友，联手打怪","l":"TF2-3","c":"心琳","g":1,"p":1},{"i":2011,"t":"缩小认知差距，做到角色互换","l":"TF3-3","c":"空林文子","g":1,"p":1},{"i":2006,"t":"原则，一种无法辩驳的力量","l":"TF2-3","c":"空林文子","g":1,"p":1},{"i":1647,"t":"谈判","l":"TF2-2","c":"娘娘","g":1,"p":1},{"i":1300,"t":"如何使谈判最有效","l":"TF1-1","c":"撒冷牧童","g":1,"p":1},{"i":350,"t":"面试初体验","l":"TF1-1","c":"卢珊","g":1,"p":1}],"ms":[{"id":8595,"topic":"谈判中如何通过不等价交易获得更多？","learn_goal":"在不等价交易的谈判中获得更多","remark":"可以说，谈判在生活中无处不在，比如，你和你上司去谈加薪，他就不给你加，怎么办？要么忍，要么走人？\r\n你和客户去谈产品价钱，明明已经是底价了，再低就赔钱了，可是客户就是不买账。哪这个生意还做不做呢？\r\n你学了谈判知道产品报价要狮子大开口，你一开口，客户转身就走了，怎么办？\r\n哪到底有没有一个原则可以化解以上所有的谈判困境呢？","level":"TF3-3","duration":60,"status":29,"type":0,"chaishujia":{"username":"莫念","city":"深圳市"},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"开场：大家好，我是莫念，今天带拆的书是《沃顿商学院最受欢迎的谈判课》。\r\n学习目标：在跟随我完成本次RIA现场学习后，学习者能够在生活中遇到谈判场景的时候（界定），使用不等价交易的方法（行为），做大共同价值，进而达到谈判双赢的效果（效果）。","ratings_count":1,"texts":[{"id":12267,"quote":"\u003cp>【R环节】\u003c/p>\u003cp>片段1（P133）\u003c/p>\u003cp>不等价交易的机会到底在哪里？\u003c/p>\u003cp>即使在商业活动中，你也可以利用非常小的东西去换取巨大的利益。我经常问高管们一些这样的问题：周一，你将装满产品的一辆卡车交付给一位客户，该客户为此支付费用。周二，你将同样产品的卡车交付给同一位客户，该客户为此支付同样的费用。然而，此外，周二你还向该客户提供了一个名字-- 仅仅是一个名字--加勒比一家服务一流却价格低廉的酒店的名字，供该客户和他妻子第二次度蜜月所用。这样一来，你周二交付的产品与周一还相同吗？\u003c/p>\u003cp>当然不同！与周一相比，你提升了你的客户在周二的生活价值。当然，只是轻微提升而已。但是，在一个竞争异常激烈的世界里，轻微地提升往往是通向成功的必要条件。\u003c/p>\u003cp>将对手当成有着数十亿神经突触的资源宝库，有些神经突触与交易有关，有些与交易无关。你点亮的神经突触越多，对方对价格的敏感度就越低，双方的关系就越融洽，交易的价值就越高。\u003c/p>","explains":"\u003cp>【场景法介绍图书 1-2分钟】\u003c/p>\u003cp>事件场景：可以说，谈判在生活中无处不在，比如，你和你上司去谈加薪，他就不给你加，你和客户去谈产品价钱，明明已经是底价了，再低就赔钱了，可是客户就是不买账，有没有？学习者：有的。这个时候我们会怎么做回应呢？学习者：要么忍，要么走人。\u003c/p>\u003cp>提问：在像加薪、和客户讨价还价、等等这些谈判场景中间，大部分时候你的表现如何呢？有没有在很多情况下都陷入了对抗和冲突的场景呢？\u003c/p>\u003cp>影响：如果持续在这样的状况中间，又不做任何的改变的话，最终势必会影响到你的职场目标和生活目标的达成。 \u003c/p>\u003cp>解决：如何打破这样的困境呢？今天这本《沃顿商学院最受欢迎的谈判课》就通过详实的真实谈判场景给我们带来了12条非常实用的双赢谈判原则。而今天我们要学习的就是：不等价交易这条非常实用的谈判原则。\u003c/p>\u003cp>【片段一的学习目标】\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习中能够在生活中遇到谈判场景的时候（界定），运用寻找不等价交易的三步法找到不等价交易的机会（行为），进而可以在谈判过程中做大共同价值，达到谈判双赢的效果（效果）。\u003c/p>","interaction":"\u003cp>【I环节】\u003c/p>\u003cp>具体怎么找到不等价交易的机会呢？片段中间给到了我们一个什么方法？学习者：“去找到更多生活中间的价值”。片段中给到的方法是：去找到更多的无形价值。什么是无形价值呢？因为我们是在跟活生生的人在谈判，不是机器，对吗？用文中作者的话：要把对手当成有着数十亿神经突触的资源宝库。举个我自己的例子。有一次我在淘宝上买一块41元的白板，商品详情里介绍送一支马克笔+四颗磁粒。我希望能送我15颗磁粒，但我知道如果我直接这么开口，很可能遭到拒绝。于是我想到“不等价交易”，首先马克笔对我没什么用，于是我对客服说：“你好，马克笔我就不需要了，你们留着有用。”客服非常感激，可能在我之前从来没人这么说过。于是我继续说：“用马克笔换些磁粒吧。”客服爽快地说：“可以，您下单备注下吧。”于是我备注了“不要笔，送15颗磁粒。”客服马上就说：“磁粒最多送10颗噢。”我继续使用“不等价交易”说：“是这样的，几颗磁粒对你们可能不算什么，但对我有重要意义。收到商品后我会给你们五星好评的。”结果对方也很开心，很容易想到，客服同意了。\u003c/p>\u003cp>笔和好评对我不重要，但对他们重要。磁粒对他们不算什么，但对我有意义。我们来看哈，还是41元的商品，我们彼此通过不等价交易获得了更多。而且关键是这中间我还交付了一个无形价值，是什么？这一天我是不是稍微提高了一点客户的生活质量？对啦，收获了一位非常nice、有同情心、礼貌、懂得换位思考的买家。\u003c/p>\u003cp>好，结合片段和我自己的这个案例，怎么找到这个不等价交易的机会呢？这里我总结了三个步骤：\u003c/p>\u003cp>【HOW】\u003c/p>\u003cp>1：代入：把自己代入到对方的处境，想人所想，急人所急，爱人所爱，恶人所恶。客服一天的工作是很辛苦的。\u003c/p>\u003cp>2：发掘：发掘对方真实需求，找到对他真正重要的东西。我的案例中间，对方真正重要的是5星好评。\u003c/p>\u003cp>3：找出：找出那些对你是举手之劳，却对别人很重要的东西。我给出五星好评只是顺手的事情，对方却很看重。\u003c/p>\u003cp>关于以上的三步，我讲清楚了没有？好的，我们拆书帮最讲的就是拆为己用，下边我们来通过编一个剧本来演练一下这个方法。\u003c/p>\u003cp>【A2】（编一个剧本）\u003c/p>\u003cp>经过上述的讲解，我相信大家对不等价交易这一谈判原则已经有了一个基本的了解。下面我们演练一下。\u003c/p>\u003cp>【A2指令】下面请大家设想一个未来一周或者一个月你工作或生活中间的一个可以用到找不等价交易机会的这一谈判方法的场景。比如生活中间的像，国庆长假你和你男朋友商量去哪里旅游，你呢希望可以来一个购物之旅，所以希望去香港、纽约这样的大都市，而你男朋友则想来一个热带雨林或者海岛山野游，因为每天呆在大城市实在是太累，终于放个假希望好好休息放松一下，希望人越少越好。或者是其他的你可以想到的类似的场景。\u003c/p>\u003cp>想到这个场景之后，请你自己编一个和自己有关的小剧本，设计出任务、情节变化（包括：起因、经过、结果）和当时双方的对话、动作等，其中的对话用到识别不等价交易的谈判方法。把关键词写到空白页上。时间3分钟，3分钟后我请一位小伙伴分享他的剧本。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>学习者：大家好，因为我是两个小孩的爸爸，所以我就说一个在暑假的时候可能和我孩子的一个谈判的场景。\u003c/p>\u003cp>现在就是暑假，孩子就想尽量多玩，我的目标是他可以去学打篮球。我计划先就带他去爬山，然后回来很累的时候，我就会带孩子去电影院，去看NBA有关的一个篮球的电影-《决战慕尼黑》，看完孩子就会很羡慕里边的篮球明星。\u003c/p>\u003cp>第一步：代入对方的处境。孩子肯定是想多玩，我作为父亲就是希望告诉孩子，玩的同时还可以学到篮球的技能，磨炼自己的意志力，这是第一步。\u003c/p>\u003cp>第二步：发掘，就是发掘他真正的需求，因为小孩子现在都比较叛逆，同时也都有自己崇拜的偶像。我就是希望他可以成为班里其他孩子的偶像，可能这样也是他的真正需求。\u003c/p>\u003cp>第三步：找出对我是举手之劳，对方却很在乎的事情。我会每天给孩子鼓励、给他点赞。这个作为父亲我来说是举手之劳的，可是每个孩子获得这些鼓励触动作用还是非常大的。\u003c/p>\u003cp>拆书家：好，非常棒，下边我们剧本开始了，您请。\u003c/p>\u003cp>学习者：我准备明天早上和孩子展开这个谈判。明天早上起来，我会把孩子叫过来：儿子，你现在暑假过得挺有意思的吧？玩得也很高兴吧？今天我们去爬爬山吧？儿子：好 。 爬山结束以后就会很累啦，然后我会对儿子说：爬山确实有点累，我们去换个轻松的，我们一块去看个电影吧。我会带他去看这个最近上映的有关篮球的励志电影-《决战慕尼黑》，到时候就在电影高潮的时候，我会对儿子说：爸爸也想你像电影里边这些篮球明星一样，你觉得呢？你在暑假的时候开始练习篮球的话，开学以后没准也能成为你同学的偶像哦，儿子，你觉得呢？后边行动开始以后，我就会每天给他点赞，鼓励，这个对我来说只是举手之劳。\u003c/p>\u003cp>拆书家：太棒了，给徐爸爸一个掌声，徐爸爸直接就有学以致用直接有用到我们今天学到的方法。给大家回顾一下。第一步，徐爸爸有代入自己儿子的场景，对吧？就是儿子暑假就是喜欢玩，对吧？\u003c/p>\u003cp>第二步，发掘儿子的真实需求，为什么这么喜欢玩呢？是因为青春期也都希望别的孩子崇拜自己，所以徐爸爸就设置了一个场景，先去爬山，然后带他去电影院里边看偶像的电影。\u003c/p>\u003cp>然后第三步，找出对爸爸是举手之劳，可是儿子却很看重的事情。就是每天给儿子点赞、鼓励，对父亲来说就是一句话的事情，可是对儿子来说是很看重的，是吧？\u003c/p>\u003cp>【过渡】\u003c/p>\u003cp>好，当我们找到了这个不等价交易的机会，然后我们可以怎么具体来完成这个交换呢？你可能会说：哪还不简单，直接交换就可以了哈，真的这么简单吗？请看下一个片段。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":12268,"quote":"\u003cp>【片段二的学习目标】\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习中能够在生活中遇到谈判场景的时候（界定），使用不等价交易的三步法，（界定）做大蛋糕，再进行谈判，进而达到谈判双赢的效果（效果）。\u003c/p>\u003cp>在看片段之前。先给大家发一份自测题，请大家不做深度思考根据自己的第一直觉填写就可以。分值是1-5分，非常符合是5分，非常不符合是1分。做完后，计算一下你的总分是多少。&nbsp;\u003c/p>\u003cp>【A1自测题】\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>状况描述\u003c/p>\u003c/td>\u003ctd>\u003cp>非常不符合\u003c/p>\u003c/td>\u003ctd>\u003cp>不符合\u003c/p>\u003c/td>\u003ctd>\u003cp>一般\u003c/p>\u003c/td>\u003ctd>\u003cp>符合\u003c/p>\u003c/td>\u003ctd>\u003cp>非常符合\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>1.我总能留意到那些对我来说只是举手之劳，却对别人很重要的东西。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2.每次客户让我的产品降价，我总能找到除价格一位的因素和客户交换，以维持产品利润。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3.在和客户合作时，我总能把自己代入到对方的处境，想象出此时对方脑海中的画面。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4.我总可以在网上购物的时候，通过五星好评获得卖家送我的小礼物。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5.在职场中我总能通过提供一些力所能及的帮助给同事，因此而收获了很多意外的惊喜。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>【I环节】解释量表的意义\u003c/p>\u003cp>大家做完了吗？好的，这份自测题的目的是为了看看大家在找到不等价交易价值部分的能力，如果是20分以上的小伙伴说明在工作和生活中你有经常运用不等价交易这个原则，而且常常遇到贵人，相当不错， 如果是10-20分，说明关于不等价交易这个谈判原则你还有提升的空间。10分以下的小伙伴，说明这个原则对你来说还是一个陌生的概念哦。\u003c/p>\u003cp>这份自测题只针对不等价交易这一个谈判技巧，所以并不是对你谈判能力的定性的结论，供大家的参考。\u003c/p>\u003cp>接下来，请小伙伴帮我给发一下拆页。大家读完后请给我一个示意。谢谢。\u003c/p>\u003cp>片段2（P131页）\u003c/p>\u003cp>在日常生活的谈判中利用价值不等之物进行交易。谈判各方衡量价值的方式各不相同，对价值大小所持看法往往也不同。一旦找出哪些各方对其价值大小持不同看法的东西，就可以利用其进行交易。在这个过程中，你会得到你认为对你有价值的东西，作为交换，你可以放弃对自己而言价值相对较小的东西。在谈判中，利用价值不等之物进行交易会使谈判项目的总体数量或价值增加，双方关系将更融洽，信任度将会提高，你自己对对方的价值也就增加，让双方都可以获得更多。\u003c/p>","explains":"\u003cp>【I重述原文-4分钟】\u003c/p>\u003cp>【强化讲解概念的I】片段给我们讲了一个非常实用的谈判概念：价值不等之物。如何理解这个概念呢？举个例子，\u003c/p>\u003cp>同样的我手里的这瓶水，超市里边一般卖多少钱？学习者：3-5块吧。水可以干嘛，解渴，好，什么情况下边，我这瓶水可以卖到1公斤黄金的价格呢？学习者：沙漠里边。你快渴死了，你手头有一袋黄金，我手里还有两瓶水，这个时候我和你说，金子给我，这瓶水就给你，你很可能非常痛快得就答应了。\u003c/p>\u003cp>&nbsp;同样的一瓶水，我和你共同认可的价值是什么？\u003c/p>\u003cp>请大家看这两张图：这里的价值相等之物，指的就是对于同一件物品，双方都都能看到并且认可的那部分价值。这瓶水可以解渴，这个价值我们双方都认可，对吧？学习者：对的。所以不等价交易第一步是\u003cstrong>首先识别出等价之物的部分，这是整个谈判交换的起点和基础。这里就是双方都知道水可以解渴、金子值\u003c/strong>\u003cstrong>10w\u003c/strong>\u003cstrong>块钱，这是我们双方都认可的水和金子的价值，对吗？而你手里刚好只有什么？对，一袋金子却没有水，快渴死了，而我刚好有什么？对，两瓶水却没有金子。\u003c/strong>（关键点1）关于什么是价值相等之物我说明白了吗？对，双方都能看到并且认可的那部分价值。\u003c/p>\u003cp>这里的这瓶水除了能解渴还有什么功能？能救你的命对吧？而我因为手里有两瓶水，这个时候我手里的这瓶水的价值一下子就上来了，大家说是不是？这里的不等价的部分出来了：由于我们的需求、经历、处境不一样，对于同一件物品，这里是这瓶水，人们主观认可的价值完全不一样：这时候，这瓶水不但能解渴，而且还可以救你一命。所以不等价交易的\u003cstrong>第二步是找出不等价的部分，这里的不等价的部分就是水除了解渴还可以救你一命。你手里的金子值\u003c/strong>\u003cstrong>10w\u003c/strong>\u003cstrong>块钱，可是前提是先活下来，而我也知道你手里的金子值10w\u003c/strong>\u003cstrong>块钱，可是我没有，我也没有生命危险。这里你手里的金子和我手里的水在我们双方的眼里的价值是不一样的。关于什么是同一件物品的不等价的部分我说明白了吗？为什么会产生不等价的部分？学习者：由于我们的需求、经历、处境不一样，对于同一件物品，我们主观认可的价值完全不一样，而这个不一样的部分就是物品的不等价的部分。\u003c/strong>（关键点2）\u003c/p>\u003cp>这个时候恰恰你手里有一袋金子（假设值10w块），而我没有，大家看第二张图，此时这袋金子你看到的价值是：值十万块钱+可以救我自己一命，我看到的价值是：值十万块钱+我没有+我可以用水救你一命。所以结果怎么样？你很开心得把金子给了我，我给了你一瓶水，对吧？ 我得到了一袋黄金很开心、你活了下来也很开心，对吧，双赢。这里的水和金子就是不等价之物，所以大家看不等价交易\u003cstrong>第三步就是用双方的不等价之物进行交换\u003c/strong>\u003cstrong> &nbsp;\u003c/strong>\u003cstrong>，我用水换了你手里的金子。\u003c/strong>（关键点3）\u003c/p>\u003cp>【概念对比】\u003c/p>\u003cp>哪什么时候用这个方法呢？不等价交易相对应的一个概念是等价交易，如果我手里也没水了，也只有一袋金子，你会和我交换吗？学习者：肯定不会。没必要了，对不。所以不等价交易的前提一定是\u003cstrong>双方都能满足对方的当前需求，这是整个谈判的基础。\u003c/strong> \u003c/p>\u003cp>【how步骤】\u003c/p>\u003cp>好结合片段和刚才的拆解我这里个大家总结得出不等价交易的三个步骤：\u003c/p>\u003cp>1：\u003cstrong>首先识别出等价之物的部分；水解渴\u003c/strong>\u003cstrong>+\u003c/strong>\u003cstrong>金子值10w\u003c/strong>\u003cstrong>块钱。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>：第二步是找出不等价的部分；我：水可以解渴+\u003c/strong>\u003cstrong>没有金子；你：水可以救命+\u003c/strong>\u003cstrong>有金子。这里的不等价的部分，指的是同一件物品还是不一样的物品？学习者：同一件物品。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>：第三步就是用双方的不等价之物进行交换。我用水交换了你的金子。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>不等价交易的前提一定是\u003cstrong>双方都能满足对方的当前需求，这是整个谈判的基础、如果这个基础不存在了，就不适合运用这个方法。\u003c/strong>\u003c/p>","interaction":"\u003cp>【A3环节微行动学习-- 33分钟】\u003c/p>\u003cp>【引导讨论】\u003c/p>\u003cp>好，下面请大家设想一个各位自己会面临的一个谈判的画面，这个场景画面会在未来的一周或者一个月发生，在画面中你可能是在和你的上司、同事、爱人、孩子或者父母就某一个你很在乎的目标进行谈判，谈了一段你发现没有任何进展，这个时候你想到了我们今天学到的不等价交易的原则，你问了自己一个问题，这个谈判过程中等价之物的部分是什么？不等价的部分是什么？怎么用不等价之物进行交换呢？好，想到这个场景可以和身边的小组伙伴分享讨论。\u003c/p>\u003cp>时间暂定为5分钟，我们看到时候大家讨论到什么程度。\u003c/p>\u003cp>拆书家：在刚才的讨论中，大家有没有想到自己的一个应用场景？学习者：有的。好，下边我们用今天学到的这个方法，想想怎么应用今天学到的这个不等价交易的三个步骤，去准备你的这场谈判呢？\u003c/p>\u003cp>拆书家：有拿几组的小伙伴运用到了这个方法，举一下手。\u003c/p>\u003cp>好，\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>我会在我的课程推广中运用这个方法，我的课程对我来说是举手之劳的，因为我的课程已经出来了，而这个对于来听课的女孩子确是很重要的—每个女孩子都喜欢变得更美。我的产品是芳香精油，很多时候他们买了不知道什么时候用，或者具体的用法不清晰，我可以通过这个课程的分享，最终帮助到我的产品销售。\u003c/p>\u003cp>【拆书家】非常感谢莉莉的分享。好，刚才每个小组都分享了自己的应用场景。这位我问一下大家。\u003c/p>\u003cp>在运用这个三步法的过程中，大家感觉那个步骤最有难度？为什么？\u003c/p>\u003cp>【学习者】发现不等价的部分最难。\u003c/p>\u003cp>【明确问题】\u003c/p>\u003cp>【拆书家】大家都觉得第二步最难，对吗。【学习者】：是的，第二步，怎么找到不等价部分最难。\u003c/p>\u003cp>好，大家都感觉第二步最难，其他组认同吗？有补充吗？\u003c/p>\u003cp>那么我们进行下一步，请就这个问题的根本原因，在小组内讨论，探究可行的解决方案。时间3分钟，看大家能给出多少思路来。由组长记录在白纸上边。\u003c/p>\u003cp>【讨论问题的本质】【拆书家】\u003c/p>\u003cp>这个问题的本质也就是根本原因到底是什么，为什么第二步为什么这么难呢？\u003c/p>\u003cp>学习者A：不了解对方的真实需求。\u003c/p>\u003cp>学习者B：代入不了对方的真实处境。\u003c/p>\u003cp>学习者C：双方对于这个物品的价值认同的不一样。\u003c/p>\u003cp>学习者D：双方的价值观有差异。\u003c/p>\u003cp>【拆书家】：如果非得选一个，最根本、最重要的原因的话，大家觉得是哪一个？\u003c/p>\u003cp>【学习者】：不了解对方的真实需求。\u003c/p>\u003cp>【拆书家】：好，大家都认为不了解对方的真实需求才是找不到不等价交易部分的根本原因，对吗？【学习者】对的。\u003c/p>\u003cp>【讨论解决方案】\u003c/p>\u003cp>【拆书家】：好，哪我们现在分组来讨论一下怎么可以更好地去找到对方的真实需求呢？从这边开始，每三位小伙伴一组。4分钟的时间，大家注意，每一个组选一个小伙伴负责记录，小伙伴们可以从各种角度来提问讨论最终形成解决方案。\u003c/p>\u003cp>【拆书家】：第二组的小伙伴来分享一下你们的方案。\u003c/p>\u003cp>【学习者1】：第一：通过对话、提问、的方式来了解对方的真实需求。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 第二：各种调研的方式：百度、背景调查、第三方的数据。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 第三：主动发起提议。\u003c/p>\u003cp>【拆书家】：这一组的小伙伴还有什么补充呢？\u003c/p>\u003cp>【学习者2】：我们补充的一点是要有相关的情境匹配，来提出问题。\u003c/p>\u003cp>【学习者3】：我们可以用场景匹配的方式来提问。\u003c/p>\u003cp>【拆书家】：可以再具体一点吗？\u003c/p>\u003cp>【学习者4】：通过先抛出自己的需求，然后再来引导对方讲出他的真实需求。\u003c/p>\u003cp>【拆书家】：我们来一块总结一下。整个我们提炼出来了3个大的步骤，如何去找到对方的真实需求，如果按照时间维度来看的话。\u003c/p>\u003cp>1：先做背景调研。\u003c/p>\u003cp>2：先让对方先出牌，通过提问的方式，让对方的需求展示出来。（匹配情境）。\u003c/p>\u003cp>3：抛出自己的需求，让对方来匹配。\u003c/p>\u003cp>好，当我们做完这些工作以后，我们是不是可以更进一步了解对方的真实需求了呢？哪有了这个作为基础，接下来我们是不是就可以更好地去找到不等价交易的部分了呢？而不是一开始我们就去找不等价的部分。\u003c/p>\u003cp>【学习者】：是的。\u003c/p>\u003cp>【拆书家】：好，关于这个大家共创出来的—如何去找到对方的真实需求，大家还有其他的补充的吗？\u003c/p>\u003cp>【A2】催化应用\u003c/p>\u003cp>【找人分享】【A2指令】今天我们学习了不等价交易的谈判原则。那希望小伙伴们在接下来的一周里，能够把这个方法分享给自己的朋友或者家人。让自己和身边的人都可以从输赢思维转换到双赢思维。那我们该如何分享给我们的朋友呢？你会和谁去分享呢？写下来，在什么时候分享呢？在哪里分享呢？你会分享的内容是什么？请大家再次回想今天分享的内容，并把你想分享的内容记录在便签上。给大家一分钟的时间写一下。\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>【学习者1】我会在下次朋友淘宝买东西的时候，可能就是下周，给他分享今天学到的这个不等价交易的方法。让他可以通过五星好评，获得更多。\u003c/p>\u003cp>【总结发言】\u003c/p>\u003cp>不等价交易原则是非常实用的谈判原则，我自己就是最大的受益者，和所有的技能一样，知易行难，这里送给大家一个独门秘籍，六个字：练习、练习、练习，我今天的分享就到这里，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1565369684000,"updated_at":1565369684000,"ria":true},{"id":8051,"topic":"TF2-1过级","learn_goal":"超先森TF2-1过级","remark":"TF2-1过级","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"超先森","city":"石家庄市"},"club":{"name":"石家庄梧桐分舵","city":"石家庄"},"prologue":"\u003cp>【自我介绍】\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>各位小伙伴，大家好，我是超先森，来自石家庄梧桐分舵。我的三个标签是自我管理、阅读、早起。今年的目标是成为一名三级拆书家。今天挑战的是TF2-1的过级。目前现场有4个小伙伴，4人人为一组，组长为 Mona&nbsp; 。\r\n &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>【图书介绍】\r\n&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>首先向大家推荐下我今天拆的书籍《沃顿商学院自控课》。\r\n&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>&nbsp; F: 《沃顿商学院自控课》的作者是刘丽娜，书中从调节神经链、远离镜像自我、hold住关键点等8部分讲述了全球百年名校之一沃顿商学院“沃顿式”的自控教育。沃顿自控教育得到越来越多人的认可，更是培养出许多如巴菲特、波萨克、哈里森等杰出人物。\r\n&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>&nbsp;A：这本书是自我管理类图书中非常畅销的一本，和其他同类书籍相比，该书内容丰富，不仅有系统性的原理，更有切实的可行性操作方法，书中穿插着一些案例，通过分析，更容易让人理解，行文很生动。学过课程的人声称这门课程可以改变一生。\r\n&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>&nbsp;B：小伙伴们曾经是否给自己设立了很多目标，但是往往因为诱惑、注意力、情绪等问题而无法坚持，那么推荐你阅读这本书，通过这本书可以解决个人自控力不足的烦恼，突破自我提升的障碍，能够让自己成为更优秀的个体，通过运用自控，掌控自我，不断实现自己的价值。\r\n &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>【学习目标】\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>今天分享的主题是建立自我控制条约，通过分享，可以让学习者不再仅通过自身的主观力量，还可以使用三步法来制定出在外界力量帮助下可以坚持下来的计划。&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":11638,"quote":"\u003cp>强大如尤利西斯，在面对海妖的诱惑时，尚且要借助外物的力量，而不单单是靠内心的信仰和操守。平凡如你我，之所以每每违背自己原先制订的计划，而去做一些短期收益的事情，是因为我们过于依赖于主观世界的力量，换句话说，我们过分相信自己，并且在违背了之前制订的计划以后，并未得到即刻的惩罚。\u003c/p>\u003cp>所以，想要做到自控，除了要依赖自身的主观力量外，我们更要学会借助外物的力量。&nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>如何才能建立起自我控制条件？多拉认为，以下三条可在一定程度上帮助到你：\u003c/p>\u003cp>● 向你的亲朋好友公布自己的目标，使其督促、鞭挞你可以始终如一地执行下去；\u003c/p>\u003cp>● 在脑海中多次演练不执行原有计划的后果，这样会使你体会到缺乏自律所造成的严重后果；\u003c/p>\u003cp>● 提升个人自我惩罚力度，如如果我没有按照计划执行的话，我就……当然，这件事情必须是对自己有一定惩罚力度的事情。\u003c/p>","explains":"\u003cp>\u003cstrong>What：\u003c/strong>我们在实现计划，建立自我控制条约时，不能仅仅依靠自信、信仰、操守等主观力量，还需要学会借助外物的力量。\u003c/p>\u003cp>\u003cstrong>Why:（融入不那么做的坏处）\u003c/strong>我们很多人都希望通过改变让自己变得越来越好，甚至会树立很多目标，开始的时候信誓旦旦，甚至会写详细计划，但是坚持了一段时间后，就会因为过度相信自己，忽视外部力量，而无法坚持下来。比如睡觉前，自己信誓旦旦说要明天要早起跑步，可是如果没有闹钟、早起打卡群、类似如果不准时起床跑步就给朋友发100元红包这样惩处措施等这些外部力量的话，自己往往会以“我太累了，想再睡一会儿”“明天再说吧”等各种理由给自己找借口，导致计划失败。所以，过度相信自己，忽视外部力量，最直接的坏处就是计划就容易“泡汤”，更糟糕的是计划的失败会影响自己的心情，会容易产生后悔、沮丧、失落、暴躁等各种负面情绪，这些消极能量的长期存在会影响自己正常的工作、生活。\u003c/p>\u003cp>\u003cstrong>How：\u003c/strong>那么该如何在依靠主观力量的同时，通过外物力量，为自己建立自控力条约呢？拆页中介绍了具体方法\u003c/p>\u003cp>一是把自己的计划、目标告诉亲朋好友，让他们监督，营造督促环境\u003c/p>\u003cp>二是在大脑中多次模拟演练不执行原计划后果，让自己感受后果\u003c/p>\u003cp>三是构建惩处机制，一旦自己没按原计划执行，便有惩罚，提高破坏计划的成本\u003c/p>\u003cp>\u003cstrong>适用边界：\u003c/strong>拆页介绍的方法不是“万能药”，只是在一定程度上能够更好的帮助我们去实现计划，因此不能有“学会这个，马上就能自控”的心理。另外拆页介绍的方法因人而异，不适合所有人，比如那些不制定目标、喜欢随性自在的人。\u003c/p>\u003cp>\u003cstrong>失败案例：\u003c/strong>\u003c/p>\u003cp>2019年元旦，新年新气象，自己想要养成早起的习惯，计划以21天为周期，每周期要比上一周期要提前5分钟起床，直到养成5点半起床的习惯。刚开始的时候，自己也是信心满满，但不到2个星期就坚持不下来了，自己内心一度受挫，现在想来，是自己太相信自己了，没有借助外部力量。\u003c/p>\u003cp>\u003cstrong>成功案例：\u003c/strong>\u003c/p>\u003cp>3月初，我在看了《沃顿商学院自控课》，了解了这个方法后，在依靠主观力量的基础上，开始有意识的借助外力帮助自己早起。\u003c/p>\u003cp>一是将这个计划告诉老婆，她很支持（前提是早起可以，但别打扰他和孩子），让她监督我。同时，和拆书帮梧桐分舵的另外3个小伙伴组建早起打卡群，每天坚持早起。\u003c/p>\u003cp>二是在遇到自己实在起不来的时候，就反复模拟如果自己不早起做计划好的早起任务，那么心情就会不好，容易工作出错，然后被领导批评，联想到被领导批评的场景，也就瞬间精神了。\u003c/p>\u003cp>三是给自己设置了惩罚措施，就是如何坚持不了，每周失败的次数等于每周做家务的样数。\u003c/p>\u003cp>结果我发现自己已经坚持2个多月的早起，到现在自己已经能够从原来的早上7点起床到现在的6点15前起床。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>分享完我的案例\u003cstrong>，\u003c/strong>接下来请小伙伴们配合我一下，认真听下面的内容，看电影听音乐、刷朋友圈、闲聊、看抖音、玩游戏、浏览明星八卦、购物......，在上述等内容中，有哪些是你在日常生活、工作中最容易受到诱惑而放下手头事情的，比如计划要在1小时内看20页的书，却中途拿起手机刷起了抖音，结果计划落空；或者打算上午完成3个计划目标，但是却和同事聊起了八卦，结果目标只完成2个；又或者晚上决定11:00睡觉，结果11:00的时候自己还在追剧等等。回想下，自己最近一次违背预先制定的计划时，是什么时候？是因为什么内容让自己打断了计划的执行？请大家在小组内分享一下，大概3分钟时间，讨论结束后，我们会请小伙伴们分享一下\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>1.今年2月份，春节放假回来之后，考虑到快餐之类的食物，油很大，我想吃的健康点，于是就决定自己带饭，然后到单位热。想着晚上把菜切好，第2天早上把菜炒好装盒。结果晚饭结束后，自己就躺在沙发上刷淘宝之类的APP，一直刷到晚上11:00左右，然后就睡了，晚上切菜，第2天炒菜没有执行，自己带饭的目标没有实现。隔天快餐、外卖依旧。\u003c/p>\u003cp>2.4月初，自己想要早起，定的目标是6:00起床。为了让自己起来，还设定了循环闹钟。但是自己实在太困了，抵制不了想要继续睡的诱惑，于是闹钟响起后关了接着睡，导致自己早起计划失败。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A1+\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计\u003c/strong>\u003c/p>\u003cp>听了小伙伴门的分享后，我们再来回顾下拆页介绍的方法：一是向亲朋好友展现目标、计划，立flag，使其监督；二是多次演练不执行计划的后果。三是构建惩处机制。那么接下来，大家结合自己刚才分享的案例，如果回到当时的那个情境，或遇到类似的情况，用我们今天了解到的方法，你将如何优化当时遇到的诱惑和问题，让自己当时的计划能够继续执行下去？请大家继续在组内分享一下。时间为4分钟，然后我们找一位小伙伴来分享。\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>学习者案例记录\u003c/p>\u003cp>我的目标是为了让自己吃得健康点，自己带饭到单位\u003cbr>\u003c/p>\u003cp>1.我会将自己带饭的计划告诉同事，明确第2天会带什么菜，比如西红柿炒鸡蛋，让同事们监督我，形成督促环境。\u003c/p>\u003cp>2.如果自己不想执行带饭计划，我会在大脑中反复演练自己不执行计划的后果，2月份天气比较冷，办公室比较暖和，如果没有带饭，自己就要出去买，因为温差较大，自己可能会感冒。而且一些快餐食品没有卫生保障，如果自己吃了不卫生的食物，容易出现拉肚子，急性肠胃炎等。想到自己不带饭会带来这么多的麻烦，有利于督促自己去执行计划。\u003c/p>\u003cp>3.构建惩处机制，一是卸载购物APP； 二是在白纸上写下自己没有执行计划的经过，让同事们看，接受同事们的嘲笑；三是 随机给三个同事发10元红包。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1559401917000,"updated_at":1559402008000,"ria":true},{"id":5452,"topic":"如何提高谈判能力，争取更多权益","learn_goal":"在谈判过程中，双方分歧很大时，能利用对方的准则，争取更多权益","remark":"","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"黄茂林","city":"深圳市"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"Ｆ：“沃顿商学院最受欢迎的谈判课”这本书的作者在沃顿商学院开设谈判课以来，连续13年被学生评为最受欢迎的谈判课。这本书就是根据这些经验提炼而成。\r\nＡ：和同类书籍不同之处在于，作者强调谈判并非得到一切，而是争取更多。所以，本书的谈判技巧是着重于在合理范围内争取更多利益。在当当上，超过6万条的评论，好评率99.6%，可见它的受欢迎程度。\r\nＢ：在日常生活和工作中，谈判无处不在，如果你想提高谈判能力，推荐你去看这本书；它从生活到工作，教你如何提高自己的谈判能力;如果碰到不公正的待遇，双方分歧很大时，本书会教你如何运用对方认可的“准则”，来为自己争取更多的利益。\r\n大家有没有碰到过这种情况，我们在订购某种服务时，事前对方都承诺的很好，到事后出现了一些状况，对方的售后却完全不是那么回事，各种推脱。和他们据理力争吧，还很影响心情。\r\n那么有没有一种好的方式，来保护我们的权益呢？","ratings_count":1,"texts":[{"id":8620,"quote":"\u003cp>反复强调准则的利用以及本书所提供的所有建议都体现了这样的观点：\u003cstrong>要采取循序渐进的策略，将谈判分成多个步骤。\u003c/strong>大部分谈判经验不足的人往往要求对方一次迈出一大步，他们要求对方从当前位置一下子跳到自己所希望的位置。例如，“我的电脑坏了，给我一台新的。”\u003c/p>\u003cp>让对方迈出如此大的一步很容易遭到对方的拒绝。大的步子似乎风险更大，它和当前的状态差别太大。\u003c/p>\u003cp>所以，你\u003cstrong>应该将谈判划分成一个个比较小的步骤，每一步都要停靠并确认一下。\u003c/strong>每一个停靠点相互之间的距离不能太远。通过这些渐进式步骤，你可以将对方带到很远的地方。你要一次一小步地带领对方从熟悉的内容逐渐到不熟悉的内容。\u003c/p>\u003cp>本质上，在每一种情况下，这样做都是在为说服对方迈出下一步打基础。如果对方问你的目标是什么，告诉他们你正在努力确认他们的准则，以便找到在目前的状况下有可能采取的方案。如果对方问你更多问题，披露一些能让你更接近目标的信息。“这种情况下怎样做才有可能呢”要比“我想让你给我便宜20％”更有效，因为后面这种问法要求对方迈的步子太大。\u003c/p>\u003cp>只有后退足够远的距离，对方才会既无法拒绝你所提出的要求，又不会产生被你利用的感觉。从对方脑海中的各种画面开始。准则的含义即是对方脑海中的一幅画面。在谈判中大多数人后退的距离远远不够。要从对方所熟悉的内容开始，然后再一步一步地缓缓前进。\u003c/p>\u003cp>我所说的后退到足够远的距离是什么意思呢？例如，这些问题：“您想达成一项协议吗？”“您想赚钱吗？”“您想让客户满意吗？”这为谈判提供了一个停靠点。如果对方一开始说他们希望达成一项协议，但之后却开始提出蛮横无理的要求。你可以问对方，这样的要求如何与他们希望达成协议的说法相符合。\u003c/p>\u003cp>在谈判中，应该一步一步地带领对方从熟悉的内容到不熟悉的内容。情况越复杂，迈的步子要越小，所需步骤要越多。\u003c/p>\u003cp>对方脑海中的画面应该简单明确，从中找出一些让对方无法拒绝而你又可以接受的东西。\u003c/p>\u003cp>下面就是一个从熟悉内容开始采取渐进策略的例子。我的一个学生名叫洛基·穆特瓦尼，他去位于费城西部的机动车辆管理局缴纳交通违规罚款。在那里，他看到一个巨大的标示牌，上面写着：禁止使用个人支票缴费。洛基只带了个人支票，他决定去看看能否就此事协商一下。\u003c/p>\u003cp>他环顾四周，想找到一个准则。他发现，自己的交通违规罚单背面有一个地址，供人邮寄个人支票。这个地址看起来有些熟悉。\u003c/p>\u003cp>洛基走近窗口。“我的罚单背面上说，我可以按照上面所写的地址将个人支票邮寄过去，是吗？”洛基对工作人员说。“是的。”工作人员回答说。\u003c/p>\u003cp>“可是上面这个地址具体在哪里呢？”洛基问。“就是这栋大楼。”工作人员说。\u003c/p>\u003cp>洛基停顿了片刻。“邮寄过来的支票会放到这栋大楼的具体什么地方呢？”洛基问。“哦，就放在那边那张桌子那儿。”工作人员一边说，一边用手指着大约6英尺外的一张桌子。\u003c/p>\u003cp>“真的吗？”洛基沉吟了一下说，“我能问您一个问题吗？那6英尺有什么特别之处吗？6英尺以外，个人支票可以使用；6英尺以内，个人支票就不能使用……如果我现在拿着我的支票，将它放入信封寄给您，这张支票就会来到那边的那张桌子上，您觉得怎么样？这样我可以用支票缴费了吗？我还会贴上邮票。”\u003c/p>\u003cp>洛基那天缴费用的是个人支票吗？是的。而在他前面的3000人就没有做到这一点，也许在他后面的3000人也没有做到这一点。不过，对洛基表现出的那丝讽刺挖苦，你可能不太喜欢。如果是你，可能会这样问，就禁止使用个人支票这一规定，你们是否曾有过例外情况？重点是，洛基通过指出机动车辆管理局在其规定上存在明显的矛盾，从而实现了自己的目标。如果洛基当时在谈判中想一步到位，（“如果我可以将个人支票邮寄到这儿，为什么就不能亲自用支票缴费呢？”）那名工作人员所要迈的步子很可能就太大了，他需要看清这个思维过程的每一个步骤。\u003c/p>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>什么叫“准则”？谁能用一句话告诉我？\u003c/p>\u003cp>作者定义的“准则”不是客观准则或你认为公平的准则，而是对方认为公平合理的准则。\u003c/p>\u003cp>这个准则可能是某条政策、条款或对方遵循的惯例，但一定是对方所认可的。\u003c/p>\u003cp>为什么用准则可以为我们争取更多利益？\u003c/p>\u003cp>这位帅哥，待会能麻烦你去电梯口帮我拿个东西么？（可以）好的，那麻烦你帮我走一趟，谢谢！不用真去拿，刚只是做个演示。\u003c/p>\u003cp>来采访下这位帅哥，如果刚才我不询问你，直接叫你去帮我拿个东西，你会去么？可能不会，就算会去，心理也会不舒服对吗？那么在我询问之后，你刚才直接就去了，这是为什么？因为你承诺了。当然这个拿下东西的阻力太小，并不是这样做都行，我举这个案例，是想告诉大家，口头或书面的承诺更容易促使对方行动。\u003c/p>\u003cp>所以在使用准则时，有个小技巧，你可以让对方再次给你承诺，或是重申他的“准则”。\u003c/p>\u003cp>那么如何使用准则来为我们争取权益？\u003c/p>\u003cp>我们回看原文，我加粗的那两句话“\u003cstrong>要采取循序渐进的策略，将谈判分成多个步骤\u003c/strong>”并且“\u003cstrong>将谈判划分成一个个比较小的步骤，每一步都要停靠并确认一下\u003c/strong>”。\u003c/p>\u003cp>细化行动步骤：这些建议不太好操作，为了让大家更好的理解，我将他细化成四步：\u003c/p>\u003cp>　　第一、找到准则，并和对方确认；\u003c/p>\u003cp>第二、和对方明确这条准则的具体含义，并把对自己有利的因素溶入其中；\u003c/p>\u003cp>第三、向对方提出疑问，说出你的遭遇和准则相矛盾的点；\u003c/p>\u003cp>第四、询问对方应该如何处理。\u003c/p>\u003cp>在我们的日常生活和工作中，如果碰到售前和售后不一致的情况，你们会怎么做？举个例子，你买了个电器，承诺坏了三个月内包换，但你刚用两个月就坏了，对方却说只能帮你修，你会怎么办？通常来说，我们都是问题抛出来，把对方的条款拿出来，强迫对方来解决，对么。但大家有没有发现，刚才这四步中，前两步都没提任何问题，第三步都没提要求，仅仅只是告诉对方我碰到这个问题。这就是循序渐进的真谛，前期不和对方产生对立情绪，只有当双方共同接受准则之后，再提要求。\u003c/p>\u003cp>我再来详细讲下这四步，第一，如何找到对方认可的准则？我们可以对方提供的文件、广告、或是标语中寻找；如果没有这方面的文字资料，也可以从对方惯例的做法中寻找。记住，找到之后，一定要和对方确认，需要得到他的认可。\u003c/p>\u003cp>第二，这个是重点，很多时候，同一条款或词语我们的认知是不一致的，这个时候，需要重新定义这个条款，让对方来解释这个准则的具体含义，这里特别注意，你需要明确对你有利的解释让对方来确认。\u003c/p>\u003cp>第三步，这个时候依然别急着怼人，把你的遭遇客观的描述出来，并指出准则相矛盾的点。 \u003c/p>\u003cp>　　第四步，询问对方该如何解决，他提出解决方案后，你可以反对，但别一开始就抛出自己的要求。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>　　最后，有一点需要大家注意，那就是不要在有第三方人员在场时使用，这会增加你被拒绝的概率。另外，每个技巧都不是万能的，但这个技巧可以提高你谈判的成功率。\u003c/p>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>接下来，我们来试着自己来应用这个技巧，快递是我们经常接触的行业，它提供了极大的便利，有时却会碰到很糟心的时候，小美从深圳寄了两箱荔枝回老家，结果收到时荔枝一大部分都变黑了，完全没法吃，一箱荔枝将近三百块，跑去找快递公司，快递公司答复物品没丢，所以不关他们的事，然而在快递前，他们明确表态运荔枝没问题，他们运过很多。现在，请大家小组讨论下，假如你是小美，你会如何运用今天所学的知识，尽可能的为自己争取更多的权益。（原文下半部分附快递单背面条款）\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>我们用五分钟讨论下，待会我会请两个小伙伴上来演示，一个代表快递公司，一个代表小美。请记住，运用今天的知识属于新知，这是个练手的机会，别太在意结果，注重过程，如何运用新的谈判技巧。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>学习者（小美）：您好！我想确认一个条款，我在贵公司的快递单背面有看到一个条款，意思是如果由于你们的原因导致的物件损坏，你们会有相应的赔偿责任，请问是这样的吗？\u003c/p>\u003cp>学习者（快递客户经理）：是的。\u003c/p>\u003cp>学习者（小美）：你们出的这个条款就是为了当出现损坏时，用来保障客户的权益，减少他们的损失对吗？\u003c/p>\u003cp>学习者（快递客户经理）：是的。\u003c/p>\u003cp>学习者（小美）：那我想请问下，如果我寄了水果或是杯子，然后收到的时候烂了，不能用了，这个算损坏的范围吗？\u003c/p>\u003cp>学习者（快递客户经理）：是的。\u003c/p>\u003cp>学习者（小美）：是这样的，我前两天从这边寄了两箱荔枝到老家，收到时已经烂了，不能吃了，请问这个可以赔偿吗？\u003c/p>\u003cp>学习者（快递客户经理）：可以。\u003c/p>\u003cp>拆书家回应：这个客户很厉害，这个客服也很配合。刚才我们的小美很聪明，她先是夸了对方的条款很注重客户的利益，然后又举了一个相似的案例，她先假设如果寄水果坏了有没有赔偿，然后在客服回应有时，再来描述自己的经历，从而达到让快递公司赔付的目的。非常好的应用了今天所讲的内容，我们讲的利用“准则”进行谈判就是这样，先把自己的诉求放在最后，先去寻找对方的准则，再和对方确认这个准则的具体含义，最后再提出自己碰到的情况正好满足这样的条件，从而达到自己的要求。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>我今天的分享就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1530630983000,"updated_at":1530630983000,"ria":true},{"id":5244,"topic":"循序渐进地沟通法则","learn_goal":"学习循序渐进的沟通法则”智慧”，变得更从容达成目的。","remark":"在你的身边，有的人就是能拿到卖家的低价。他们砍价时，不是对商品吹毛求疵压低价格，这会让卖家觉得你是在贬低商品，会让双方都尬聊，交易不下去。学习循序渐进的沟通法则”智慧”，变得更从容达成目的。","level":"TF2-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"无敌","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"\u003cp>我先来分组，这里3个人到“墨竹”，3个人到“伯约”，余下2人一组。&nbsp;\u003c/p>\u003cp>我是无敌，我今天拆TF2-1。我非常喜欢自己的网名无敌，能够让大家很快就记住，回忆起来也很容易。我是一个坚持的金牛座，坚持印象笔记的晨间日记500天。&nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>【FAB介绍图书】\u003c/p>\u003cp>F：今天我带来的这本书是《沃顿商学院最受欢迎的谈判课》，作者斯图尔特·戴蒙德，服务过一半以上的世界500强企业，他的谈判曾经成功解决过好莱坞编剧大罢工。我看的这本书是2014年出版，印刷第30次。\u003c/p>\u003cp>A：本书一张图都没有，用的都是外国的例子，但为什么能够在豆瓣有2815人评价？相比其他同类书籍，本书提供了一章谈判工具清单，使人容易知道如何开始、催化、结束谈判。\u003c/p>\u003cp>B：这本书封面英文Getting More让我们获得更多。如果你正在沟通上司获得更多晋升机会、授权同事做工作获得更多自己做事时间、沟通家人得到更多理解、或者在购物时拿下更多优惠、你可以买来阅读一下。\u003c/p>","ratings_count":1,"texts":[{"id":8363,"quote":"\u003col>\u003cli>\u003cp>下面开始阅读拆页，看完这一页的内容\u003c/p>\u003c/li>\u003c/ol>","explains":"\u003cp>【I：讲解引导】\u003c/p>\u003cp>我在拆页上做了一些笔记，总结成3+1+2。拆页的开始总结了全书的经验：\u003c/p>\u003cul>\u003cli>\u003cp>①有意识的强调利用准则\u003c/p>\u003c/li>\u003cli>\u003cp>②采用循序渐进的策略\u003c/p>\u003c/li>\u003cli>\u003cp>③将谈判分成多个步骤\u003c/p>\u003c/li>\u003c/ul>\u003cp>总结为1句话是：一次一小步带领对方从熟悉的内容逐渐到不熟悉的内容。\u003c/p>\u003cp>比如买东西时，大部分人会直接砍价格，卖家不降价你也没辙。另一种情况是，你更喜欢去不砍价的地方买。如何更有效的在交易中获得更多，拆页告诉我们两点：\u003c/p>\u003cp>\u003cstrong>1、利用对方准则中有利自己的内容\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、披露给对方，接近你目标的消息\u003c/strong>\u003c/p>\u003cp>【适用条件】\u003c/p>\u003cp>越是复杂项目或亲密的人际关系中，越适合用到这个方法；如果和你的交谈对象是没有准则的，则不适用这个方法。\u003c/p>\u003cp>【不那么做的坏处】\u003c/p>\u003cp>善于沟通的好处很多，但如果在工作中，有人想要增加你的新工作，你因为总觉得自己不善沟通，往往会直接就接受了，于是总会多出了一些分外的工作。\u003c/p>\u003cp>\u003cstrong>（举例）\u003c/strong>我的一次经历是，我在朋友推荐下，和老婆去一家婚纱摄影店咨询，这是我们咨询的第二家。我老婆谈判后拿到了更为优惠的实际成交价格。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>服务种类\u003c/p>\u003c/td>\u003ctd>\u003cp>门市价格\u003c/p>\u003c/td>\u003ctd>\u003cp>实际成交\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>服装数量\u003c/p>\u003c/td>\u003ctd>\u003cp>4套\u003c/p>\u003c/td>\u003ctd>\u003cp>5套\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>场地数量\u003c/p>\u003c/td>\u003ctd>\u003cp>3场地/套，总数不少于12场\u003c/p>\u003c/td>\u003ctd>\u003cp>总数不少于15场\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>相片数量\u003c/p>\u003c/td>\u003ctd>\u003cp>120张\u003c/p>\u003c/td>\u003ctd>\u003cp>140张\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>精修照片数量\u003c/p>\u003c/td>\u003ctd>\u003cp>45张（自费加拍160元/张）\u003c/p>\u003c/td>\u003ctd>\u003cp>55张\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>价格\u003c/p>\u003c/td>\u003ctd>\u003cp>5999\u003c/p>\u003c/td>\u003ctd>\u003cp>5999\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cbr>我老婆与销售人谈价格会说到：\u003c/p>\u003cp>\u003cstrong>（利用对方的准则）\u003c/strong>店里承诺熟人介绍是会优惠的；\u003c/p>\u003cp>\u003cstrong>（披露消息）\u003c/strong>第一家店直接给升级到5套服装，并且她有同事近期也要拍婚纱照。\u003c/p>\u003cp>对方听到这里，会有什么样的内心变化呢？刚才说到的两条又符合片段中的哪一点呢？大家都有一定的判断了。\u003c/p>","interaction":"\u003cp>【A1：激活经验】\u003c/p>\u003cp>请想想你在过去的一周中频繁沟通的人，某个事情，你和他说了几次都不成功，或者你觉得说了也没有用。比如，老公在做着事情，但你想让老公去帮你做一件事；又到了项目交付的阶段，你想请同事帮忙改文件；孩子放学后，你想让他去做作业；在618，双11，冲动的很想买买买，你想要价格便宜点或者拿到更多赠品。把时间、地点、人物写下来，给大家2分钟（留1分钟听听大家想到的事例）。\u003c/p>\u003cp>\u003cstrong>【\u003cstrong>小小 分享\u003c/strong>】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>时间：\u003c/strong>上周\u003cbr>\u003c/p>\u003cp>\u003cstrong>地点：\u003c/strong>北京，几次电话沟通\u003cbr>\u003c/p>\u003cp>\u003cstrong>人物：\u003c/strong>小小和业务代理（小小是厂家的一名销售、沟通的对方是一个代理商）\u003c/p>\u003cp>\u003cstrong>场景：\u003c/strong>代理拿到一个投标项目，代理想要保密标底，避免被其他代理抢走客户，所以迟迟没有给小小报标底参数，而小小作为厂家销售要掌握这个标书。反复沟通过了几次。\u003cbr>\u003c/p>\u003cp>\u003cstrong>拆书家反馈：\u003c/strong>\u003cbr>\u003c/p>\u003cp>这是一个工作中的例子，进行了多回合的沟通，小小想要达到的沟通目标还没有实现，事情不能总停止不做。我们继续拆书学习。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>【A1+：反思加工】\u003c/p>\u003cp>\u003cstrong>（指令）\u003c/strong>想想你刚做过的练习中，回到相同场景下，思考一下这件事的步骤，用到拆页方法，在小组里分享，时间5分钟，结束时，我找一位小伙伴分享自己的案例。\u003cbr>\u003c/p>\u003cp>\u003cstrong>【分享者 A1+】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（场景）\u003c/strong>他和同学，3人合租两室，与房主签订租房合同。3人住不下2室的房子，分享者希望安装隔断，希望同少加点钱，但房东要求加钱较多。现在一直谈不拢。\u003c/p>\u003cp>\u003cstrong>（利用对方的准则）\u003c/strong>在当初的合同中有写着租房价格和入住是3人。\u003c/p>\u003cp>\u003cstrong>（披露消息\u003c/strong>）新的北京市住房政策，他们是够条件去租公租房的，冬季是淡季，房东会因为空置，而损失租金。\u003c/p>\u003cp>\u003cstrong>拆书家反馈：\u003c/strong>\u003cbr>\u003c/p>\u003cp>提供服务的地方，都是会有约定，租房就是服务。你可以从租房合同里找到准则，3人住两室，是住不下的。\u003c/p>\u003cp>披露消息，你可以向房主说明，你可以少赚一点，但他会得到稳定的客户，和在他监管下的房屋改造。\u003c/p>\u003cp>\u003cbr>【结束语】\u003cbr>\u003c/p>\u003cp>我把今天的知识归纳为，3个意识、1句总结、2个方法。第一次用不熟练，可以事先复习今天的拆页，帮助自己从容沟通。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1528006978000,"updated_at":1541910153000,"ria":true},{"id":5205,"topic":"如何应用准则提高谈判能力","learn_goal":"提高谈判能力","remark":"","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"黄茂林","city":"深圳市"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，很高兴今天为大家带拆一本我很喜欢的谈判类书籍。“沃顿商学院最受欢迎的谈判课”这本书的作者在沃顿商学院开设谈判课以来，连续13年被评为最受欢迎的谈判课。本书和其它类谈判类书籍最大的不同在于，并非所有谈判都是以金钱为核心，他可以是各种无形之物。\r\n在我们的日常工作中，有没有碰过这种情况，客户一直在压价格，而你又不能接受这种低价，从而导致僵持在那。有什么方法可以让我们即不用降价，又能让客户接受？\r\n这就是我今天要跟大家分享的内容，请用2分钟阅读原文。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":8316,"quote":"\u003cp>\u003cstrong>不等价交换\u003c/strong>\u003c/p>\u003cp>这个技巧就是利用价值不等之物进行交易。谈判各方衡量价值的方式各不相同，对价值大小所持看法往往也不同。一旦找出那些各方对其价值大小持不同看法的东西，就可以利用其进行交易。在这个过程中，你会得到你认为对你有价值的东西，作为交换，你可以放弃对自己而言价值相对较小的东西。\u003c/p>\u003cp>“不等价交易”会告诉你应该怎样做。首先，必须搞清楚对方脑海中的画面。然后，必须搞清楚你自己脑海中的画面。找出对一方而言价值不太大但对另一方很有价值的东西。之后，利用这些东西进行交易。\u003c/p>\u003cp>对方脑海中的画面不一定与交易本身有关，它们可以与交易以外的任何事物相关。事实上，越是将整个世界看做是自己潜在的资源宝库，就越容易发现对方的心中所想。\u003c/p>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>在开始之前，我们先来分下组，四个人一组，正好分三组。\u003c/p>\u003cp>什么叫“不等价交换”，同一个物品，因为衡量标准不一样，它的价值也不相同。\u003c/p>\u003cp>所以在谈判中，如果我们能找到对对方来说价值相对较高，而对我们来说价值不高的东西，我们就比较容易达成一致。这里需要强调的是，用来交换的，不一定是物品，也可以是无形的东西，比如说你可以帮他节约时间，或是提供增值服务等。\u003c/p>\u003cp>如何运用“不等价交换”，原文帮我们总结了三点：\u003c/p>\u003cp>一、你要了解对方，知道那些是他看重的，或是需要的；\u003c/p>\u003cp>二、清楚自身的资源；\u003c/p>\u003cp>三、找出对方所看重的，而对你来说价值又不高的东西，然后拿来做交易。\u003c/p>\u003cp>举个例子来讲，以前我们公司搞活动招新会员时，经常会赠送一个大礼包，一个会籍卡十万，赠送十二万的礼品，这些东西确实是十二万，只不过我们有内部渠道，成本可能可能只要五六万，但客户却会觉得十万拿到十二万的礼品，还有会籍身份，这个超值。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>接下来，我们小组讨论下，在我们之前的工作中，有没有碰到双方看重的都是价钱，或是各自的利益，从而导致谈判僵持甚至是失败的？ &nbsp; \u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>我们用三分钟时间讨论下，然后我会请一位小伙伴分享下你们小组的经验。\u003c/p>\u003cp>学习者:之前我们去谈一个项目合作，我们想借助对方的平台推广我们的新产品，合作方式和分成模式都谈好了，对方却强调必需先支付2万才能帮我们上线，而我们老板希望能通过后期成交的分成来支付，所以不同意支付，后面就因为这个没谈好就蹦了。\u003c/p>\u003cp>拆书家回应：感谢这个伙伴的分享，你们公司是觉得后期的分成足以支付这个费用，但对方却强调必须先收钱。双方都看重自己的利益，所以导致无法达成一致。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>好的，我们刚探讨的是过往的失败经历，接下来，我们来思考下，如何运用刚才所学的内容。 \u003c/p>\u003cp>现在，请大家想一想，在我们工作或生活中，那些地方是可以用到这个技巧的。它可以是工作的商务洽谈，也可以是生活中。 \u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>接下来，请用一分钟的时间，在你的便签上写上，你准备什么时候做这件事？请写出具体的行动方案。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>学习者:我们宝安准备换场地，正好我周六要去和场地方谈判，他们是一个新开的茶室，肯定需要人气，而我们每周都有活动，刚好是他们需要的，所以我准备这样和他说：一、你们新开，正好需要人气，而我们每周都有活动，这可以帮你们很好的宣传；\u003c/p>\u003cp>二、茶室也需要客户经常来，但如果没有主题活动，他们就没有来的动力，而我们每周的活动内容都不一样，我们可以给你几个免费的名额，这可以作为你们的增值服务，免费给到客户，这还能成为你们的特色。\u003c/p>\u003cp>这样他们就会觉得很值，但我们给几个名额其实是没什么成本的。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1527435608000,"updated_at":1530864187000,"ria":true},{"id":4465,"topic":"用不等价交易实现你的谈判目标","learn_goal":"用不等价交易实现你的谈判目标","remark":" 谈判不仅发生在商业环境中，在和孩子交流、工作、旅行和购物中等都会用到谈判，有没有一种方式可以帮你争取更多，祝你获取更多利益呢。安妮会分享一个在谈判中行之有效的方法---利用不等价交易实现你的目标。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"安妮","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"大家好！我是安妮，很高兴今天正式开始我的拆书之旅。首先自我介绍一下，我是一名英语学习爱好者，从大学1年级起，就从没放弃过英语的业余学习。第二个标签:目前是一名领导力研究者，虽然我只是一个普通员工，但是我发现在工作中建立了影响力和领导力会让你的工作事半功倍。第三个就是希望在拆书帮达成的，知识体系架构师和分享者。以上是我的三个标签，大家相聚在拆书帮是缘分，为什拆书帮有这么大的吸引力呢？拆书的理念来源于赵周老师的一本书《这样读书就够了》，拆书是一种学习方法论，拆不是拆散，而是转化和内化强调把图书中的知识转化为学习者的能力。适用于以提升能力、解决问题为目标的成人学习，强调的是以学习者为中心而不是以知识为中心。分为个人学习的拆书法和组织学习的拆书法：个人学习的应用是RIA 便签读书法。R 代表的是图书片段，reading，I代表的是interpretation 也就是对于原文知识的理解和解读。A：appropriation 这个环节就是我们要拆己用。回顾过往经历同时催化未来行动。组织学习的应用是一位拆书家会拿出一本书的片段加工出一场现场学习，引导和促进一群人拆为己用。从学习者的学习效果衡量的话","ratings_count":0,"texts":[{"id":7477,"quote":null,"explains":"\u003cp>今天分享的是《沃顿商学院最受欢迎的谈判课》作者斯图尔特·戴蒙德，这本书有非常多的基于业务场景的谈判，而且有特别丰富的实例，我们可以直接用在工作生活中。是《华尔街日报》商业管理类畅销书榜NO.1，当我们学会了谈判，可以在生活中各个方面争取的更多。来自本书的132页，给大家30秒的时间阅读以下书中的片段。\u003c/p>\u003cp>谈判不仅发生商业环境中，同时也发生在我们每天的工作生活中。在工作中我们经常需要跨部门的谈判；在我们购买东西或者租房子的过程中，我们也需要谈判。今天分享给大家的是在谈判中一个非常重要的非等价交易的原理，谈判过程中，由于双方对于价值的衡量各不相同，那么对于价值的大小所持的看法往往也不同。一旦找出双方对其价值大小不同看法的的东西，就可以进行交易。这就是利用价值不等之物进行的不等价交易。比如说租房的时候，房东的孩子刚好需要英文的辅导，你可以帮助实现辅导。这时候房东很有可能就会用较低的价格把房子租给你。其实这就是一种不等价值交易。对于房东来说孩子的教育比“租金”的价值更大。不等价交易背后有一个关键的驱动力就是“无形之物”。即除金钱以外对对方同样有价值的东西。因此对于明码标价的谈判不是特别适合采用非等价值交易，比如超市购买物品。使用不等价交易能够在谈判过程中，能够降低对方对价格的敏感度，双方的关系也会更融洽。如何做到非等价值交易，文中提出了三个步骤：\u003c/p>\u003cp>1.&nbsp; 搞清楚对方脑海中的画面，也就是对于对方来说对方的需求有哪些。这个需求不一定和交易本身有关。\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp;&nbsp; 搞清楚自己脑海中的画面，也就是你的行为背后真正的目标是什么。\u003c/p>\u003cp>找出对一方价值不大但对另一方很有价值的东西，然后利用这些东西进行交换。【预防异议】不是非得对于其中一方价值不大，而是两者有差异即可。\u003c/p>","interaction":"\u003cp>【A1 激活经验】\u003c/p>\u003cp>2季度的时候，我们正在和一家银行客户谈一个非常重要的项目，但是这个项目的竞争比较激烈，有很多竞争对手都在盯着项目，几家公司的实力差异不是特别大。我们每个人对于这个项目的胜算都没有特别大的把握。有一天晚上，客户发了一条朋友圈，说自己的苹果手机坏了，我们的售前同事，看到这条朋友圈，然后立马给客户发了一条微信，说自己可以修。然后晚上去客户那里取手机，并且连夜给客户把手机修好了。客户第二天拿到手机非常的感动。从这以后我们的项目就出现了新的进展，客户在之后和我们交流的特别积极，终于也在最后拿下了这个几百万的项目。虽然修手机的事情只是一个小的插曲，但是确是问题解决的关键，这也在无形中证明了向客户证明了不惜一切让客户满足。其实这就是利用不等价交易进行谈判。\u003c/p>\u003cp>【A2 催化行动】\u003cbr>\u003c/p>\u003cp>不等价交易的力量这么大，春节假期之后，通常是老板考虑员工升职涨薪的时候，虽然我的业绩在团队中还不错，但是我认为自己谈判的价值和胜算还不是特别大，因此可以用非等价交易做谈判的准备。\u003c/p>\u003cp>1.&nbsp; 搞清楚对方脑海中的画面。对于我们老板来讲，升职加薪的时候，除了对于业绩要求之外，和员工关系，以及上级领导对员工的认可。对于她属于无形价值，也是她同样看重的。\u003c/p>\u003cp>2.&nbsp; 自己脑海中的画面，我希望老板为我升职加薪，这样的话每年就会有更多的存款出去旅游，同时更多结余的钱给到爸妈。\u003c/p>\u003cp>3.上级老板的肯定（老板的老板）以及和员工之间的关系是我的老板尤其看重的，这就在我老板那里变成具有更高价值的，这就是不等价物。那么我就需要和上级领导（老板的老板）建立更融洽的关系，增强她对我的了解，我发现我的上级领导非常喜欢看话剧，最近元旦的时候，有一个好看的话剧上演，我打算和上级老板一起去看，和她多交流，让她更多的了解我。同时和员工关系上，由于我自己是团队中的新人，总是闷头做事情，和团队中的相处比较少，年底我们要做新的计划，我会主动向老板申请，承担一部分的负责工作，加强和大家的交流。加上今年不错的业绩，增加谈判的价值。\u003cbr>\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1515899030000,"updated_at":1515899181000},{"id":3873,"topic":"换种思路谈判","learn_goal":"学会在谈判中争取更多","remark":"","level":"TF2-4","duration":55,"status":0,"type":0,"chaishujia":{"username":"哆啦","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"谈判无处不在。\r\n谈判的过程既不是迫使对方按照你的意愿行事，也不是让对方按照你的思路思考。而是让对方理解你想让他们理解的观念，让对方感受到你想他们感受的。\r\n你应该成为谈判过程中的主导者。周二静安寺场，来和哆啦一起，探讨一下谈判的艺术。","ratings_count":0,"texts":[{"id":6809,"quote":"\u003cp>\u003cstrong>打招呼+分组 &nbsp;FAB图书介绍【3分钟，片段1共3分钟，2-4共3分钟】\u003c/strong>\u003c/p>\u003cp>大家好，我是今天的拆书家，哆啦。\u003c/p>\u003cp>（F）《沃顿商学院最受欢迎的谈判课》这本书就是书如其名，主要讲的是商务场合中的谈判技巧。并且在书中作者提出了一个新的观点，那就是：“为自己争取更多”原则。以前我们总听说谈判“双赢”，这本书提出的新观点告诉我们，如果以今天的失利换取明天更大的利益要更加明智。\u003c/p>\u003cp>（A）这本书被推行为职场必读经典，是美国沃顿商学院极负盛名的必修课程，同时本书的课程和观点也被众多知名企业，如谷歌、微软、日本的东芝、松下等奉为职场培训圣经。这在同类别的畅销书中是非常难得一见的。\u003c/p>\u003cp>（B）每一个生活的环境，都会有谈判发生，比如我们去向老板谈升职加薪、向同事谈自己的方案设计；或者生活中，向商贩讨价还价、向房东要更多的优惠等等，当我们真正学会了谈判，在生活中的各个方面都可以争取更多。想要争取更多的伙伴，这本书不能错过了。\u003c/p>\u003cp>\u003cstrong>R·阅读原书拆页【1分钟，片段1共4分钟，2-4共4分钟】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>□2-4要求：两个拆页至少一个包含HOW的内容；有一定逻辑关系；且总内容未超过4页图书内页。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步是与对方进行有效沟通：\u003c/strong>了解他们所发出的信号，尤其是当他们来自另一种文化。如果对方开始发出“关系信号”，这说明他们有兴趣了解你是否值得他们信任。关系信号包括谈论一些非商业性话题，如娱乐、体育运动、饮食以及音乐。\u003c/p>\u003cp>\u003cstrong>接下来，你要公开承认双方存在差异。\u003c/strong>如果你和对方之间存在差异，或至少被认为与对方之间存在差异，那么，你对此越是坦诚，就越会赢得对方的信任。即使对方指出你对他们的了解还不够充分，你可以向他们表示歉意，人们首先看重的就是坦诚。\u003c/p>\u003cp>\u003cstrong>之后，找一个出发点。\u003c/strong>接受对方的任何安排，无论事情多么微小琐碎，如座次的安排、应该点什么饮料等等。如果对方或其文化中有令你产生好感的东西，不防大方予以赞扬肯定。如果你曾观察过对方的文化，或读过与对方文化有关的一些内容，你可以将此作为谈论话题，并询问对方你所说的是否正确。如果不正确，怎样才正确呢？始终对对方充满好奇心。\u003c/p>","explains":"\u003cp>\u003cstrong>I环节【5分钟，片段1共9分钟，2-4共9分钟】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>□2-4要求：涵盖二级的4种讲解引导技巧。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>本拆页涵盖：\u003c/strong>\u003cstrong>1）强调不那么做的坏处；2）给出了学习者可能异议的预防性讲解；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>强调学习目标：\u003c/strong>在跟随我完成这个片段的RIA之后，大家可以通过有效沟通、公开承认双方存在差异以及找一个出发点，这三个步骤，来完成一场谈判的“破冰”环节。\u003c/p>\u003cp>\u003cstrong>原文讲解：\u003c/strong>这个片段教了谈判破冰的三个步骤。\u003c/p>\u003cp>第一步要捕捉“关系信号”，进行有效沟通，比如天气、时事热点、还有女生比较喜欢的明星八卦等非商务性的话题。这一步是尊重对方。\u003c/p>\u003cp>有了第一步做基础之后，第二步是展开话题，坦诚差异，坦诚无知。这是不卑不亢的表现，表现得既不委曲求全刻意迎合，也不显得自顾自说而忽视对方。这时有效的真诚的互动。\u003c/p>\u003cp>最后一步是反客为主，前两步是根据对方发出的话题轮子接话，到这一步就是要主动找到切入点开始对话。这个切入点源自你对现场环境的察言观色。 \u003c/p>\u003cp>\u003cstrong>强调不这么做的坏处\u003c/strong>：我们常说一个好的开端就成功了一半。在谈判场合，双方都抱着目的而来，如果不用心捕捉对方话语中的信号，很可能就会出现尬聊；如果不坦诚双方的差异，则会让对方感觉到虚伪不真诚；如果不寻找到一个切入点，就可能会让谈判气氛冷淡。所以说运用这3个步骤破冰，其效果直接奠定了一场谈话的基调是轻松愉快的还是紧张生硬的。\u003c/p>\u003cp>\u003cstrong>举例说明不这么做的坏处：\u003c/strong>这里跟大家分享我第一次参加的正式谈判会议的栗子。当时对方在贵州，有个人过来引导我进去，对方问我说：“您是第一次到贵州来吗？”我回答“是的”；她接着说“我们这里有特色狗肉，您远道而来一定要去尝尝”；我心里是挺排斥这个事情的，但当时还是堆着笑脸说“好啊好啊，一定要尝尝”。结果在晚宴的时候对方真的给安排了狗肉宴，我全程没有动筷子，气氛跌至冰点，特别尴尬。然后就没有然后了，整个晚上我也没有找到新的出发点展开破冰话题，简直羞愧的要钻到地缝里面去。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>运用知识点加工成正面案例：\u003c/strong>时至今日，如果我用这三个步骤来破冰，我肯定会做的更好。第一步，捕捉信息，有效沟通：\u003c/p>\u003cp>对方问我是不是第一次来贵州的时候，\u003c/p>\u003cp>我除了礼貌回答 “是的”之外，还会对捕捉到的地理信号接话 “是啊，早就听说醉美贵州了，今天终于有机会过来感受一下。”\u003c/p>\u003cp>第二步，坦诚差异：对方继续介绍当地特色的时候，我就应该坦诚的说我不吃狗肉，这样可以避免晚宴上的尴尬。\u003c/p>\u003cp>第三步，找到出发点：步入正式谈判前，我会再寻找些新的话题，例如这里的空气真的蛮好，物价也很美丽呢，有机会要来这边置业休假等等，通过这些，完成破冰，使得谈判双方变得轻松愉悦。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>预防异议（与原文内容契合）：\u003c/strong>可能有些小伙伴会有疑惑，原文第二步让我们公开坦诚差异。如果没有差异呢？那就不需要，那不妨坦诚你的认同。这一步是要我们在谈判中保持真诚坦率的态度，不管是相符合还是有差异，只要是发自内心的想法，对方都会感受到我们的诚意。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1环节【6分钟，片段1共15分钟，2-4共15分钟】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>□2-4要求：使用A1技能点的环节提问和指令清晰，学习者能根据提问中的场景联系自己过往的具体经验，且加工出如果以后遇到同等情况，可以如何做。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>回想上周一在单位，有人来找你，这个人是你的领导、你的同事，还是你的供应商呢？\u003c/p>\u003cp>你们当时准备针对什么问题来一场正式或者不正式的谈判呢？你当时是怎样展开你的谈判的？ \u003c/p>\u003cp>请大家在组内讨论一下，一会请小伙伴进行分享。\u003c/p>\u003cp>学习者（雪）的分享：我这周一接到美术馆志愿者老师的邀请，她想请我去做志愿拍照者。在她的邀请下我就过去找她聊聊。见面之后就先来了一套客套话，“你好啊，过来远不远？”之类的，然后我也向她寒暄了两句，“见到老师真的挺高兴的”。就这样一开始熟络了起来。然后她带我走进正厅的路上，走廊上我就问了些关于这个美术馆装饰的问题，我们就这样一路聊过去，最后挺顺利的。因为有了这些破冰的对话，后面切入正题就没那么尴尬了。\u003c/p>\u003cp>学习者（涛）的分享：我就上周四的时候被安排去一个客户那里谈一下软件实施的事情。因为我自己也比较内向，也从来没见过他们，客户很礼貌问我“过来一趟这么远真是麻烦了”，我也不知道说什么，就说句“还好还好不辛苦”；然后带我进去的时候问了我一些我单位的问题，我也不是一直跟进这个case的不知道怎么回答才好，一路上都挺别扭的。\u003c/p>\u003cp>好的，听了两位小伙伴的分享，有正面的也有不那么顺利的。不过我们可以发现，在一场谈判的开始，破冰环节其实是很重要的。那根据拆页的建议，如果回到当时的情景中，你会怎样开场呢？\u003c/p>\u003cp>请大家思考一下。\u003c/p>\u003cp>学习者（涛）的分享：如果再去的话，我就会观察一下对方说什么，\u003c/p>\u003cp>就像他问我“过来一趟这么远真是麻烦了”我就知道他的信号释放出来是交通，我可以再聊聊交通这个话题，吐槽一下上海这么堵啊之类的。\u003c/p>\u003cp>然后对方问我单位的事情，我就坦诚回答，知道的能说的就说，不知道不了解就坦诚自己真的不是很清楚。\u003c/p>\u003cp>然后再主动问问他们，“您这边团队多少人啊？用的软件都是我们这边的吗？”之类的。总之要终结冰点气氛啊。\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>非常好，因为时间的关系，不能让每个小伙伴都分享了。\u003c/p>\u003cp>刚才我们探讨了一场谈判开始时的破冰方法，现在我们要切入谈判的正题了。接下来的第二个拆页，我们来思考如何才能在谈判中得到更多？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":6811,"quote":"\u003cp>今天第二个拆页，在跟随我完成这个片段的RIA之后，大家可以学会使用循序渐进策略赢得谈判。\u003c/p>\u003cp>现在请大家阅读原文拆页。\u003cbr>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>R·阅读原书拆页【1分钟，片段2共1分钟，2-4共16分钟】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>□2-4要求：两个拆页至少一个包含HOW的内容；有一定逻辑关系；且总内容未超过4页图书内页。\u003c/strong>\u003c/p>\u003cp>大多数谈判采取的都是\u003cstrong>循序渐进的策略：并非一次提出所有的要求。\u003c/strong>这是人们最难学会的事情之一。一般情况下，谈判各方并不想冒险做出任何大的改变。在每次谈判中，要想办法将谈判过程分解为小步骤。这并不需要花更长的时间，因为不这么做往往无法达成协议。\u003c/p>\u003cp>采取循序渐进策略还意味着要向对方了解有关形势，而不是单枪匹马去解决所有的问题。\u003c/p>","explains":"\u003cp>\u003cstrong>I环节【15分钟，片段2共16分钟，2-4共31分钟】（包含例子讲解）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>□2-4要求：涵盖二级的4种讲解引导技巧。本拆页涵盖：3）细化了原文行动建议的步骤。4）根据原书中案例脉络，给出了更贴近实际的例子。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>细化步骤：\u003c/strong>这个片段非常简单，就是一个循序渐进策略。那么具体要怎么做到呢？我细化了一些步骤：\u003cbr> \u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1）第一，评估你的终极目标\u003c/strong>\u003c/p>\u003cp>目标是否足够大或者足够小是因人而异的。对于万达老板王健林来说，赚1个亿就是很小的目标了。我们要针对自己的谈判目标做一个合理的评估，这个目标是不是符合业内的一般标准？如果偏差行业标准太多，这就不叫谈判了，简直是狮子大开口。评估的结果应该是实现这个谈判目标的可能性。\u003c/p>\u003cp>\u003cstrong>2）第二，将终极目标分解为几个小目标\u003c/strong>\u003c/p>\u003cp>这一步是要你根据自己的实际情况，把大的目标分割成几个小的目标。\u003c/p>\u003cp>\u003cstrong>3）第三，了解谈判对象的形势，通过多次谈判达成\u003c/strong>\u003c/p>\u003cp>这个形势就包括对方的\u003cstrong>档期、行事风格和原则\u003c/strong>。如果对方时间很紧，那可能不太适合开始一段谈判，另外选择一个没有其他事务压力的时间，会增加谈判的胜算。行事风格这个因素也是一样，可以通过对方的助理、社交圈动态、近期合作伙伴等方面判断对方是不是容易交流，是喜欢表达干练的还是喜欢感情饱满的。还有最重要的因素：原则。也就是对方的底牌、或者说最低要求。这至关重要，但也很难获得，倒是可以通过分析对方之前的商务案例、圈内口碑等来预测判断。\u003c/p>\u003cp>\u003cstrong>意译案例：\u003c/strong>（原书中举的例子是一个歪果仁在一家公司实习的例子）好的，拆解完原文之后，我给大家意译一个案例来说明一下。\u003c/p>\u003cp>大家都知道罗胖罗振宇，在他成名之前有过一艰难的时光。当时他还是个大学老师，但他想做想做央视财经栏目制片人。要实现这个目标，他必须去谈判沟通的人是时任财经频道总监郭振玺。\u003c/p>\u003cp>（评估目标）他首先评估了一下自己的终极目标，发现自己当时的资历没有砝码直接找郭谈。\u003c/p>\u003cp>（拆分目标）他的谈判目标分割成：第一进央视做基础工作，剧务跑腿都可以；第二进《对话》栏目做临时工；第三转成央视《对话》正式的总制片人。\u003c/p>\u003cp>（分析形势）郭总什么时候组织面试，他就什么时候递简历上去；郭总最看重的是资历背景，央视牛人这么多，要想跨界从新人坐起，那是肯定不会答应的。所以在第一个谈判阶段，罗胖只是争取了一个跑腿打杂的活计。这对于手持博士学位的大学老师来说，郭总还是无法拒绝的。然后通过自己不断地学习，他觉得自己有了些做制片人的底子了，就再去找郭谈，这次申请的是做点制片人的活儿，先做助理，没编制也行。后来他就成了央视唯一一个临时工制片人。紧接着干了段时间，罗胖有了实力底气，他再找郭谈判，终于到位，凭借最终的强大实力，做总制片人的目标终于实现。\u003c/p>\u003cp>\u003cstrong>强调适用边界：\u003c/strong>不过这个也是有适用边界的，如果谈判的目标比较容易被双方认可，也就是说评估结果是目标很可能达成，那就不需要做这些分解动作，不必循序渐进也很有可能一步到位。\u003c/p>","interaction":"\u003cp>\u003cstrong>A3环节【10分钟，片段2共26分钟，2-4共41分钟】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>□2-4要求：使用A3技能点的环节指令清晰，学习者可以根据拆书家设定的案例场景，进行小组讨论、应用知识点并形成一个解决方案，或是应用知识点进行组内角色扮演。\u003c/strong>\u003c/p>\u003cp>好，我们刚分享了循序渐进策略在谈判过程中的运营，那接下来请大家假想这样一个场景：按照刚才的分组，你是一个公司的员工。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 向上司提出调部门申请的谈判方案\u003c/p>\u003cp>你对自己目前的工作感到枯燥繁琐没有上升空间。周一早晨的例会，老板宣布要成立一个新的事业部，你很想加入进去，从事更有活力更有挑战性的工作，但是你知道没有现任的批准，你就不能在公司内部调换工作；你也知道，如果新部门的领导不接收，你也没办法过去。这样的场景，你会怎样运用循序渐进策略，让你的领导同意你换到新的事业部去发展呢？\u003c/p>\u003cp>接下来按照刚才的分组，可以一个做老板一个做这个职员，大家在组内讨论一下谈判方案。 \u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;第一组：向拟调入部门领导申请的谈判方案（学习者雨点和雪）\u003c/p>\u003cp>\u003cstrong>第一：评估我的谈判终极目标\u003c/strong>\u003c/p>\u003cp>我的目标是调到新的事业部去做更高的职位。但是这个目标估计很难达成，因为我新部门跟我现在做的工作总还有点差异，想要一过去就升职很苦难。\u003c/p>\u003cp>\u003cstrong>第二：拆分我的谈判目标\u003c/strong>\u003c/p>\u003cp>我可以先争取让新部门带我上车，接收我，做个基层岗位也可以；等我熟悉了那边的事务，我再申请升职。\u003c/p>\u003cp>\u003cstrong>第三：分析谈判对象的形势\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1）档期：\u003c/strong>新部门的领导才刚走马上任，手上很多事情要处理，我就不在他忙的时候打扰他了。下班前的半小时是他比较轻松的时间。\u003c/p>\u003cp>\u003cstrong>2）行事风格：\u003c/strong>新部门的领导据说是从XX集团挖过来的，出了名的干练利索，从来都不拖泥带水，喜欢下属汇报工作言简意赅说重点。\u003c/p>\u003cp>\u003cstrong>3）原则：\u003c/strong>很看重学历，不招本科以下的；不招换工作太频繁的。\u003c/p>\u003cp>最后，根据以上的评估、拆分和分析，做出以下具体的谈判方案：\u003c/p>\u003cp>一、周四下午五点半，找到新部门领导，自我介绍、递出自己的简历，说明来意，申请做新部门基层的员工，薪资不考虑；只争取得到这个机会。\u003c/p>\u003cp>二、进入新部门后，在基层岗位学习积累，找到更合适的机会（职位空缺、有新项目需要人手、或者拿出更好的方案直接要求升级别），表述来意，说明自己的实力，争取升职。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 第二组：向现任部门领导申请的谈判方案（学习者果莉和涛）\u003c/p>\u003cp>\u003cstrong>第一：评估我的谈判终极目标\u003c/strong>\u003c/p>\u003cp>我的目标是调到新的事业部去做更高的职位。但是这个目标估计很难达成，因为我现在的部门领导也不能得罪，毕竟同一个公司以后还有很多对接。\u003c/p>\u003cp>\u003cstrong>第二：拆分我的谈判目标\u003c/strong>\u003c/p>\u003cp>我可以先争取让现部门领导给我一个学习的机会，多学习公司其他的事情；然后再向她推荐我这个岗位可以胜任的人选，争取到把接替人带上正常轨道的缓冲期；最后新人接替我，我完成交接后去新部门报到。\u003c/p>\u003cp>\u003cstrong>第三：分析谈判对象的形势\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1）档期：\u003c/strong>现部门领导一般都在上午临近午休时有空。\u003c/p>\u003cp>\u003cstrong>2）行事风格：\u003c/strong>现部门领导是工作狂，事情总是无缝衔接做的非常到位。\u003c/p>\u003cp>\u003cstrong>3）原则：\u003c/strong>最恨不负责任的年轻人，甩手离职留下烂摊子需要她来收拾。\u003c/p>\u003cp>最后，根据以上的评估、拆分和分析，做出以下具体的谈判方案：\u003c/p>\u003cp>一、工作日上午11:00，找现任领导谈，标明自己很想学习一些新的知识，这样对公司的业务也会有更多更好的了解。但是我只是利用业务时间去其他部门串串，学习交流，不会耽误本职工作，也不占用现在岗位的工作时间。而且在这期间我都随时standby。\u003c/p>\u003cp>二、学习了解的差不多之后，再找现任领导谈。说明自己的去意，新事业部的工作确实更让我觉得有兴趣，也更符合我对自己未来的规划预期。同时推荐新人接替自己，小张工作能力不错，态度也不错，我想推荐她来接我的工作。不过我等领导批示，我先把小张教会，这段时间我还在这里，直到领导觉得她可以完全胜任为止。\u003c/p>\u003cp>三、交接缓冲期之后，正式提出调到新事业部。新人接手，工作没有受到影响。再向现任领导谈，确定具体调岗时间。\u003c/p>\u003cp>\u003cstrong>回应.点评（给予肯定，1分钟，片段2共27分钟，2-4共42分钟）\u003c/strong>\u003c/p>\u003cp>非常感谢大家的讨论和非常，看到大家在演练的过程中能够逐渐熟练的运用今天所学的知识点，做出了一个清晰、可行的谈判方案，非常棒。我看到两组的方案都是按照拆页中所说的循序渐进谈判策略来制定的。\u003c/p>\u003cp>第一组的小伙伴是面向新事业部领导谈判，第二组小伙伴思考了面对现任领导的谈判方案。\u003c/p>\u003cp>两组小伙伴都选择使用循序渐进策略来达到自己最终的谈判目标。\u003c/p>\u003cp>两组童鞋都完成了评估目标、分解目标和分析谈判对象的档期、行事风格、原则等具体步骤，并且给出了非常具体的谈判方案。\u003c/p>\u003cp>两组的小伙伴都做的很赞。\u003c/p>\u003cp>所以，通过这样一个现场演练的过程，我们发现了谈判的技巧，每个人都有可能通过循序渐进的谈判策略来为自己争取更多。\u003c/p>\u003cp>刚才我们演练了循序渐进策略的具体谈判方案。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A2环节【9分钟，片段2共36分钟，2-4共51分钟】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>□2-4要求：使用A2技能点指令清晰，至少一个A2环节提问中包括情景或场景，有学习者受到启发联系到自己的具体应用场景。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>刚才我们演练了采用循序渐进策略跟老板谈判调岗的场景。请大家再设想，明年的你是不是更富有经验的员工了？你想要加薪还是升职？还是要一个人面对数千万的大单项目谈判？\u003c/p>\u003cp>明年你可能会碰到什么问题？\u003c/p>\u003cp>请大家思考一下，一会请大家来现场分享一下。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>学习者（果莉）的分享：未来拿到联想公司的大单。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>□2-4要求：分步催化中指令清晰，有学习者根据指令，规划出了以后可以如何做的具体计划。\u003c/strong>\u003c/p>\u003cp>大家都写好了吗？\u003c/p>\u003cp>这个时候，你突然意识到，我上周末不是参加了拆书活动嘛，我们的拆书活动就讲到关于谈判中循序渐进策略的三个步骤，我想应对的谈判场合，有了更好的执行步骤吗？\u003c/p>\u003cp>所以，想到了今天我们学习的拆页步骤，请大家思考一下，我们可以怎样通过评估目标、分解目标和分析谈判对象的形式这三个步骤来完成谈判，实现目标呢？\u003c/p>\u003cp>请大家根据这三个步骤，写一下将来的行动计划步骤。\u003c/p>\u003cp>学习者（果莉）的分享：\u003c/p>\u003cp>1、评估自己的目标：我的目标是明年拿下联想公司的大单。\u003c/p>\u003cp>2、分解目标：先跟业务负责人熟悉起来，再谈事务。\u003c/p>\u003cp>3、联系以前的老同事（现跳槽到联想的），让老同事帮忙把业务负责人的基本情况打听一下，各个方面的：基础信息，做事风格，平日爱好、周末常干什么等等。\u003c/p>\u003cp>分析对方的形势：\u003c/p>\u003cp>1）档期：联想公司负责这块业务的是位女性，她有一个女儿，周末还要接女儿去兴趣班。我要在周六的白天，那时候她有空，我在那时候找她谈。\u003c/p>\u003cp>2）行事风格：这个人是很重感情型的。\u003c/p>\u003cp>3）原则：只要认定你这个朋友，她不会再在意产品指标，就跟你签单。\u003c/p>\u003cp>4、成为她朋友的做法：\u003c/p>\u003cp>她女儿马上要小学升初中了，我打算在明年9月她小孩要小升初的机会，把我手上的资源介绍给她，让她小孩能上重点中学。\u003c/p>\u003cp>\u003cstrong>结束语【2分钟，片段2共38分钟，2-4共53分钟】\u003c/strong>\u003c/p>\u003cp>我们总以为，谈判是紧张的战场厮杀，但只要技巧娴熟，谈判也可以是轻松的围炉夜话;\u003c/p>\u003cp>我们总以为，谈判是残酷的你存我亡，但只要技巧娴熟，谈判也可以是和谐的共同成长。\u003c/p>\u003cp>我们总以为，谈判是狡猾的尔虞我诈，但只要技巧娴熟，谈判也可以是圆满的双赢家。\u003c/p>\u003cp>今晚，我们了解了谈判开始时破冰的方法，了解了谈判进行时循序渐进的策略。\u003c/p>\u003cp>在进行一场谈判时，愿你有愉快的开场白，也有坦诚的心态，有抵挡一切的金钟罩，也有无坚不摧的策略技巧。\u003c/p>\u003cp>学习谈判技巧，是我们发起进攻时的冲锋号，\u003c/p>\u003cp>为自己赢得更多，是我们最终胜利的号角。\u003c/p>\u003cp>非常感谢大家一个晚上的陪伴，我今天的拆书就到这里。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1508588757000,"updated_at":1508588757000,"ria":true},{"id":3507,"topic":"有技巧的使用“识别”、“倾听”、“化解”三个步骤","learn_goal":"学会有技巧的使用“识别”、“倾听”、“化解”三个步骤","remark":"","level":"TF2-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"小玲","city":"南昌"},"club":{"name":"南昌滕王阁分舵","city":"南昌"},"prologue":"大家好，欢迎大家来到拆书现场。我是吴小玲。在跟随我完成本次拆书现场学习后，我们在遇到情绪问题和情绪化的人时，不容易被挑战忍耐底线，学会有技巧的使用“识别”、“倾听”、“化解”三个步骤，有效沟通，达成双方都接受的解决目标，防止情绪暴力伤害。为了方便大家学习讨论，现场分两个组，A组和B组。","ratings_count":0,"texts":[{"id":6386,"quote":"\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 今天给大家带来一本书。F：这本书在豆瓣评分上达到7.7分——《沃顿商学院最受欢迎的谈判课》，作者斯图尔特 戴蒙德教授，是世界一流谈判专家，曾为谷歌、微软等财富500强公司提供过咨询服务，为40多个国家政府领导人做过谈判培训。A：本书内容源自戴蒙德教授在沃顿商学院谈判课的授课内容、收集的实用案例。与一般的口才类书藉相比，本书更贴合实际，更有实用性。B:学习了这本书，如同上了一系列谈判课，可以提高谈判和沟通能力。学习了这个片段，有助于增强情绪管理能力，释放潜力，为工作、生活增添新动力。&nbsp;&nbsp;\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 现在请大家看到拆页，这份拆页来自于《沃顿商学院最受欢迎的谈判课》P163页，“如何处理情绪问题以及对待情绪化的人”。给大家两分钟阅读时间，看完的小伙伴可以举手或眼神示意我。\u003c/p>\u003cp>【原文片段】\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 如何处理情绪问题以及如何对待情绪化的人：\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;识别何时对方行事与他们的目标或需求相悖。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;设法了解对方的情绪状况和看法。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 找出对方情绪、需求和目标形成的原因。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 仔细思考你的谈判风格是否对形势有益。&nbsp; \u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 进行情感补偿：让步、道歉、同情。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 设法建立信任。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 避免极端言论——极端言论只会让对方更容易情绪化。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 利用第三方及对方委托人祝你一臂之力。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 利用对方的准则。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 纠正错误的事实。\u003c/p>","explains":"\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; WHAT: 不管你的人际关系多好，也免不了会遇到情绪激动的人与你较真。理性处理、妥善对待情绪化的人，不容易却非常必要。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; WHY:&nbsp; 掉入情绪中的人，一般都急于渲泄不满、甚至不计后果。如果你没有学会控制情绪，那么遇到事态激化时，很容易被对方带偏，使双方都陷入困境。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; HOW: 如何才能妥善处理情绪问题，合理对待情绪化的人呢？原文有十点，我把它们归集为“识别、倾听和化解”三点。具体来说：\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 第一步识别。判断对方当前是否处于情绪化状态，取决于他当前的目标是发泄不满，还是解决问题。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 第二步倾听。保持冷静，让他说出心里的不满，通过引导式询问了解不满原因。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 第三步化解。包含“一个目标”、“两个原则”、“三个办法”。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 一个目标。建立双方之间信任，营造安全的交流氛围。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 两个原则。避免言辞激化矛盾；选择适用风格进行谈判化解。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 三个办法。运用让步、道歉、同情的方式进行情感补偿；利用双方都信任的第三方调解矛盾；利用对方的逻辑澄清客观错误事实。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 如果我们不按拆页学习的建议步骤去处理情绪问题，可能会使事件矛盾升级，造成“三输”的局面。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我有个同事工作能力和责任心都很强，但她不善于处理情绪问题。在长时间工作超负荷时，很容易情绪崩溃，一碰就炸。即便是领导也不能避免被怼，导致对其工作支持力度下降，增加部门整体工作难度，引发工作成绩和个人情绪的波动，陷于“三输”局面。前不久，我与这位同事产生了工作冲突，当时她掉入情绪中，越说越气，只顾发泄。我在与她的沟通中运用了这“识别、倾听和化解”三点，用了两天时间，分段式地妥善解决了情绪冲突，也保证了工作的顺利进行。\u003c/p>","interaction":"\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 【A1】激活经验（显像提问）\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 请回顾一下你自己最近一次被激怒的情境。因为你的一句话、一个动作，让对方情绪失控。我们想象一下，当时他瞪着通红的双眼，咬牙切齿，冲到你面前，几乎想把你手撕生吞！面对他的步步紧逼，出言不善，你也怒了，反唇相击，很明显你也失控了，这种状态持续了多久，怎样结束的呢？请大家运用三分钟做一个分组讨论，之后我们选一位小伙伴把刚才讨论的内容，发言分享一下。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 【学习者案例记录】一位小伙伴表述了在工作中与同事发生的争执。由于沟通中存在不同意见，双方各执一词，学习者表现得不够尊重对方，使同事认为被贬低而带入情绪。双方争执偏离事实，引发情绪矛盾，同事关系受到伤害，工作问题也没有解决好。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 【A1+】（反思加工）\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 刚才的发言讨论很热烈。足以见得生活中情绪问题还是很常见的。同样的问题，不同的方式会有相反的效果。如果时光倒流，给你一次机会去弥补不足、减少伤害，当我们再次回到刚才讨论的情境时，我们可以怎样应用到今天的“识别、倾听、化解”三步法去解决呢。请大家分组思考讨论一下，运用今天的知识点，对处理这件事有什么好处，问题是否可以有效化解。每个人都尽量表达一下，时间是2分钟。之后，我同样要请到一位小伙伴把他的反思加工，分享给大家。发言时间是1分钟。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 【学习者反思加工】一位学习者表示双方沟通中，既要倾听对方，也要倾听自己、觉察自己的不足，做好自我调整。另一位学习者表示在下次同样的沟通中，会做好三步法。在与对方沟通阐述问题，识别到对方带情绪时，倾听了解对方处于情绪中的原因，不因对方的情绪影响自己的语言，避免言辞激化矛盾。并且选择了自己适用风格进行化解——利用午饭时间，在双方都感觉安全的环境中，以聊天方式做好沟通。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 今天通过学习“识别、倾听、化解”三步情绪问题的处理方式，现场案例分享与反思加工，我也收获到很多。拆页学习顺利完成，谢谢大家，感谢小伙伴的热情参与！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1503796626000,"updated_at":1504107263000,"ria":true},{"id":3105,"topic":"循序渐进的谈判法则","learn_goal":"学习后，能够采用一步一步渐进的原则解决谈判中一些僵局的问题","remark":"《沃顿商学院最受欢迎的谈判课》中12条主要谈判策略中的第五条：谨守循序渐进这一最佳原则。","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"张馨月","city":"海口"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好！我是张馨月，创业中的全职妈妈。今天进入我的TF3-1考核，感谢各位的支持。谈判这门课与每个人都密切相关。正如沃顿商学院谈判教授斯图尔特.戴蒙德所说，谈判是人类交际活动的核心内容之一。事件场景：在我们的生活和工作中是不是经常会出现与以下事例相似的情景，例如：在购买衣物或是各种生活用品时，要求商家折价100元；亦或者是要求孩子少看一点电视、少玩一会游戏；亦或者是向老板提出加薪、升职的要求等等。其实这就是谈判，谈判无时无刻不存在我们的生活和工作中。提问：那么遇到这类场景时，你是如何进行的呢？这样处理的效果如何？我们谈判的最重要的目的是什么？影响：简单、粗暴的沟通往往会给谈判双方带来不愉快，同时也不会有好的结果；繁琐、艰涩的谈判术语行话有时反倒脱离现实，无法实操，也无法融入生活为我所用，就更无法达到我们想要争取更多的目的了。解决：《沃顿商学院最受欢迎的谈判课》这本书针对生活中经常会出现的具体场景设计了具体适当的谈判技巧，帮助我们更深入地了解谈判对方，随机应变，达到我们的目的。例如关注对方的情绪、建立关系、明确谈判目标、采取循序渐进策略、对具体情境要具体对待等技巧，让我们真正掌握谈判。","ratings_count":0,"texts":[{"id":5914,"quote":"\u003cp>\u003cstrong>学习目标：\u003c/strong>在跟随我完成本次RIA现场学习后，学习者能在谈判陷入僵局时，采用循序渐进的方法推进谈判。\u003c/p>\u003cp>那今天和大家一起分享的内容就是来自这本《沃顿商学院最受欢迎的谈判课》中12条主要谈判策略中的第五条：谨守循序渐进这一最佳原则。\u003c/p>","explains":"\u003cp>循序渐进这个词的定义是指学习工作等按照一定的步骤逐渐深入或提高。\u003c/p>\u003cp>在这个定义中强调了两个递进，一个是过程的递进，另一个是目标的递进。\u003c/p>\u003cp>过程的递进强调的是时间、轮数、操作行为的客观跨度，例如工作面试、申请学校，初试、复试、部门面试；中美关系的建交跨越几十年，巴以和谈那是跨越几个世纪，目前任在进行。\u003c/p>\u003cp>目标的递进就是内容的深入和目达成的思维过程的引导。\u003cbr>\u003c/p>\u003cp>\u003cstrong>案例：\u003c/strong>作者的学生基洛，有次去费城机动车管理局缴纳交通违规罚款。他只带了个人支票，但那儿有个牌子，写着“不收个人支票。”但他发现他的交通罚单背后有一个供个人邮寄支票的地址，地址就是眼前这儿。于是，他问工作人员：“罚单背后写着可以邮寄个人支票？对吧”工作人员确认了；他又问具体地址在哪儿，工作人员告诉他就在这个大楼；基洛接着又问邮寄过来的支票会放到哪儿，工作人员指了一个六英尺外桌子。这下基洛找到方法了，他向工作人员提议自己把支票放到信封里，然后请工作人员放到那个桌子上。最后工作人员同意了。基洛的做法，就是循序渐进的典范。如果洛基当时在谈判中想一步到位，（“如果我可以将个人支票邮寄到这儿，为什么就不能亲自用支票缴费呢？”）那名工作人员所要迈的步子很可能就太大了，他需要看清这个思维过程的每个步骤。 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>这个片段开篇就指出了\u003cstrong>不这样做的风险\u003c/strong>：一次要求过多或是过大，那么远远增大谈判风险。根据循序渐进原则，我们可以总结出来遵守这一原则的具体步骤. &nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>具体步骤：\u003c/strong> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>1、明确自己的目标。在谈判中所有的行为都应明确无误的使你更接近自己在本次谈判中的目标。 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 2、将谈判分成一个个比较小的步骤。 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>3、每一个小的步骤之间是相互接近并递进的关系。也可以说每一个步骤都是为下一步骤打基础。“每一个下限都是一个新的下限”。 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>借此方法将对方从熟悉的内容逐渐带到不熟悉的内容。对方才会既无法拒绝你所提的要求，又不会产生被你利用的感觉。 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>我们的终极任务是达成目标，争取更多对吗？那么一切的准备都是必要的。\u003c/p>","interaction":"\u003cp>\u003cstrong>A2：\u003c/strong>\u003c/p>\u003cp>谈判无时无刻不存在我们的生活中，想要争取更多，想要达到自己的目的，那么成为一个谈判高手是一个不错的选择，那么演练是最好的学习过程。\u003c/p>\u003cp>请在座的朋友编一个小故事，几百字就可以，设计出人物、情节变化，包括：起因、经过、结果和当时双方的 对话、动作等，其中部分对话请使用今天我们学习的循序渐进的谈判技巧，将摘要写在纸上。五分钟后，我们请人讲讲他的剧本。大家也可以一起讨论。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>&nbsp;\u003c/p>\u003cp>事件：在瑜伽馆中销售2880元的年卡。人物：销售人员尔康、顾客珊珊\u003c/p>\u003cp>在瑜伽馆前台，有顾客珊珊上门咨询瑜伽馆授课相关问题。下面是前台尔康和顾客珊珊的对话。（终极目标是销售年卡）\u003c/p>\u003cp>尔康：您好！你是第一次来我们的瑜伽馆是吗？\u003c/p>\u003cp>珊珊：是的！有朋友推荐说这里环境和老师都很不错，所以想来咨询一下。我朋友是这里的老会员了。\u003c/p>\u003cp>尔康：非常欢迎！我先带你参观一下我们授课的环境，现在正在授课，过一会才能结束，所以可能无法与老师沟通了，不过你可以先看一下。\u003c/p>\u003cp>珊珊：学员还挺多呢！不知道你们这里怎么收费呢？\u003c/p>\u003cp>尔康：我们是会员制的！你的朋友不就是我的的老会员嘛！不过我们追求让每一个客人都满意的原则，所以建议你可以先体验一下，如果感觉不错那么可以再办理会员卡。我们针对新朋友，有一个超值体验卡9.9元两次，一般体验过一两次，大家就会有初步的判断了。\u003c/p>\u003cp>珊珊：9.9元两次确实很便宜，好的！那么我先办一个体验卡吧。\u003c/p>\u003cp>两次体验后：\u003c/p>\u003cp>珊珊：我很喜欢这里的环境和老师，感觉练完瑜伽身体很舒服，我想继续练下去，你能给我介绍一下你们的收费吗？\u003c/p>\u003cp>尔康：很开心你这么说，谢谢你的喜欢！我们针对会员不同情况有月卡、次卡和年卡之分。毕竟瑜伽对我们身体的改变是一个循序渐进的过程，为了让我们的体验感更强我们推出了780元的月卡，每周14堂课，你可以参加任何时间段的课程，充分体验。针对工作时间比较长的客人我们推出30次卡1200元，半年有效。\u003c/p>\u003cp>珊珊：听上去不错，确实瑜伽是一个坚持长练的运动，那么针对那种想一直联系的人是否有更优惠的价格呢？\u003c/p>\u003cp>尔康：当然有了！我们一般是非常建议会员长期练下去，所以我推出了一个超级实惠的套卡——年卡2880元，相当于每月只用240月，如果每周你练5次，那么每次课程的费用只有12元，特别的划算，对吗？\u003c/p>\u003cp>珊珊：听起来不错！\u003c/p>\u003cp>尔康：如果你觉得年卡太久，也可以先办月卡再体验一个月，只是相对于年卡确实就没有那么实惠了。\u003c/p>\u003cp>珊珊：好吧！我也是特别想练得，那么就办一个年卡吧。\u003c/p>\u003cp>（尔康）对于新人来体验者推荐首次体验卡9.9元两次，之后推荐月卡780元，在顾客有很好的体验后并与学员和老师建立感情的基础之上，再顺理成章的推销年卡2880元。整个过程采用循序渐进的谈判方法完成最终销售。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1499072297000,"updated_at":1503302394000,"ria":true},{"id":2116,"topic":"化敌为友，联手打怪","learn_goal":"找出不在谈判现场的关键人物，并于谈判对手一起说服他","remark":"小到生活中买衣服，大到职场中的项目谈判，我们需要说服的不仅是眼前的这个人，更要说服他的合作伙伴，家人或领导。坐到同一桌，便是同一派，别管它是饭桌还是谈判桌。团结一致，联手打败背后的大boss。","level":"TF2-3","duration":30,"status":0,"type":0,"chaishujia":{"username":"心琳","city":"宁波"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"学习目标：通过今天的现场学习，大家可以在谈判中有意识的寻找关键第三方并发现和解决他的需求，从而赢得更多的谈判。 大家好，我是琳琳种种。大家好，我是琳琳种种。\r\n 今天的片段来自于《沃顿商学院最受欢迎的谈判课》，这本书以区别于传统方法的视角介绍一整套适用于任何人任何情景的谈判技巧。【F】\r\n 本书的作者是世界一流谈判专家，他曾为财富500强中的许多公司做过咨询服务。他的谈判课连续13年都是沃顿商学院最抢手的课程。【A】\r\n 无论是生活中买东西，还是工作中谈判会议，我们都可以选择书中适当的谈判技巧、随机应变、见招拆招，在每一个谈判中都更顺利的实现目的，并获得更多。【B】","ratings_count":0,"texts":[{"id":4763,"quote":"\u003cp>\u003cstrong>R\u003c/strong>：《沃顿商学院最受欢迎的谈判课》第二章 “第三方”\u003c/p>\u003cp>几乎在任何一场谈判中都至少会有三个人——即使有时只有两个人在场。第三个人或第三方通常指的就是这样的人，无论是真实存在的或想象中的，即谈判者认为自己必须以某种方式遵从的人。这些人也许是鬼魂和过去的精灵，也许是谈判者告之以谈判的对象——配偶、同事、朋友——在这些人面前，谈判者需要保持面子。他也有可能是老板。问题的关键是，要想实现你的目标并获得更多，你必须对这些人负责。例如，就谈判对方个人而言他也许会同意你的意见，但他/她有一个不讲道理的顶头上司。在这种情况下，你可以和对方联手找出理由去说服对方的顶头上司。斯科特·布罗德曼是一家大化学公司的一名销售经理。有一件事令他十分费解，一个新账户的采购代表不停地提要求，尽管那笔交易已经十分诱人。于是斯科特提了一些问题，想看看幕后是否存在第三方。“我发现，原来他的老板正在监视他，而且经常在事后批评他。”斯科特说。在斯科特的帮助下，这位采购代表让其老板看到了行业标准以及他们的需求得到满足的过程。“他告诉他的老板，这是他所能达成的最有利的交易。”斯科特说。最后对方同意了协议。很少有人会忽视对自己很重要的第三方的意见。当你需要对某人施加影响、而又自认为没有足够的影响力的时候，想一想对对方而言很重要的人还有谁，以及更容易受你影响的人又是谁。\u003c/p>","explains":"\u003cp>\u003cstrong>I:\u003c/strong> 这段文字大概说的在大多数谈判中，虽然坐在你对面的只有一个人，但如果你想实现自己的目的，不仅要说服你对面的这个人，还要说服对他做决定有重大影响的人，比如他的伴侣，父母或老板。\u003c/p>\u003cp>因为只是一个片段，又是英文翻译过来的，所以有些表述可能不是太好理解，我们先理一下几个重要的关联词汇吧。\u003c/p>\u003cp>首先是第一句话中的”谈判”,在本书中作者所指的谈判，不局限于在谈判桌上的很正式的商业谈判，作者认为生活工作中凡是想实现一定目的的谈话或互动其实都是一种谈判。小到去商场买衣服，大到国家级别的战略合作项目。\u003c/p>\u003cp>其次是第二行“即谈判者认为自己必须以某种方式遵从的人”，比如我之前与公司里工程部的一位同事讨论流程自动化的问题，我主张先把核心审批步骤自动化，然后依据运行情况再逐步展开。而他坚持他从头到尾的所有步骤自动化。后来发现这并不是他本人的意思。而是他背后那个追求一步到位的德国人老板的意思。这里的德国人老板就是我的谈判对手必须遵从的人，而我如果想顺利完成项目，也必须要对这位德国老板负责。\u003c/p>\u003cp>原文看明白了，现在我们来提炼一下如何通过解决不在谈判现场的关键第三方的疑虑，赢得更多的谈判。\u003c/p>\u003cp>\u003cstrong>一，找到双方一致的目标，建立和谐的谈话氛围\u003c/strong>\u003c/p>\u003cp>回到我刚才流程自动化的谈判中来，很显然我们在项目范围上产生了异议。但我们的目标都是想提高流程的自动化程度。\u003c/p>\u003cp>\u003cstrong>二，找出谈判对手背后的那个人以及他的需求。\u003c/strong>\u003c/p>\u003cp>这个人要么是对谈判者有重大影响的人，要么说真正的决策者。只有搞清楚这个人的需求或疑虑，才能有的放矢，否则说什么，开什么条件可能都是徒劳。\u003c/p>\u003cp>\u003cstrong>三，基于第三方的需求或疑虑，列举解决方案的好处，达到说服的目的。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>依照这三个步骤，我把刚才提到的在公司里经历的流程自动化的谈判加工成了一段对话，哪位小伙伴可以帮我扮演一下我的谈判对手，把对话呈现给大家。\u003c/p>\u003cp>\u003cstrong>甲：\u003c/strong>我很同意你，我的工作重点也是提高公司业务流程的自动化程度，而且在可执行的前提下，也希望加快进程。\u003c/p>\u003cp>\u003cstrong>乙：\u003c/strong>所以我们想趁热打铁，把所有的步骤都自动化。\u003c/p>\u003cp>\u003cstrong>甲：\u003c/strong>公司引进这个自动化工具不久，大家对它都寄予众望。我主导过3个自动化的项目，它并不像美国大片里的高科技武器一样无所不能。\u003c/p>\u003cp>\u003cstrong>乙：\u003c/strong>其实我对自动化也没什么概念，不清楚会做成什么样子，但是我老板说，他上一家公司的自动化程度很高，所以希望既然要做就做得彻底一点。\u003c/p>\u003cp>\u003cstrong>甲:\u003c/strong>他可能对我们这个工具不太了解，因为我已经成功开发过3个项目了，我对这个工具还是比较了解的，先从核心的审批流程开始自动化是最好的方案。这样可以让你，你老板，还有部门的其他员工渐渐接受新的工作方式，并了解这个工具的功能。运行一段时间后，再投入更多的资源扩大自动化范围。我先向你详细解释一下我的方案，然后你回去再向你老板解释一下，我想他会同意的。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在这段对话中，我先是对他的期望表示赞同，声明我们的目标是一致的。然后找到了谈判的第三方，他的德国老板，以及这个老板的需求。接着阐述了我的解决方案的合理性和优势。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>A3 促进参与\u003c/p>\u003cp>&nbsp;相信大家对化敌为友，联手说服第三方行动步骤已经很清楚了，现在让我们来做个现场演练，我这里有两张纸条，每个小组选一个，根据纸条上所描述的情境，来设计一段对话，体现出化敌为友，联手说服第三方的三个行动步骤。我给大家8分钟的准备，8分钟后请每个小组派代表来做个现场表演。\u003c/p>\u003cp>情景一：你是商场里某品牌冰箱的导购员，正在向一位男性客人推销一款价值10000元的对开门冰箱。经过简单对话，你知道这位客人已婚，同住的除了妻子和2岁的孩子，还有岳母。日常家务大多有岳母来做，岳母觉得大冰箱难以清理而且费电。请利用今天的行动步骤设计对话，共同说服该客人背后的岳母及家人，促成交易。\u003c/p>\u003cp>情景二：你是一家饭店的大堂经理，饭店推出企业年会特色晚宴。今天预定可以享受8折。你眼前的一位客人是一家500人规模企业的行政专员，他的顶头上司是行政主管，为人谨慎，对供应商的选择讲究货比三家。请利用今天的行动步骤设计对话，共同说服该客人背后的行政主管，促成交易。\u003c/p>","interaction":"\u003cp>小组一：\u003c/p>\u003cp>大堂经理：兄弟你的事情就是我的事情，我们的目标都是一样的，都是想顺利的为贵公司准备跨年晚宴。让领导和员工都满意，又有特色的晚宴\u003c/p>\u003cp>行政专员：我看了一下你们这里的环境和菜单，也基本符合我们公司的要求，但是我的主管做事比较认真，他对我的要求就是要货比三家，所以我打算再多看几家饭店，再做决定。\u003c/p>\u003cp>大堂经理：那你今天就来对了，我们这边收集了各大酒店的服务信息，我可以逐一向你介绍一下，这样你即便不亲自去各家酒店考察，也可以做货比三家。\u003c/p>\u003cp>行政专员：这样太好了，那我今天就可以向我的主管汇报几家酒店的情况，让他今天就做决定。\u003c/p>\u003cp>小组二：\u003c/p>\u003cp>店员：您想挑选什么样的冰箱呢？\u003c/p>\u003cp>客人：我实际都好说，能冷藏冷冻就可以了。\u003c/p>\u003cp>店员：这款新款双开门的冰箱你觉得怎么样？\u003c/p>\u003cp>客人：这会不会难打理啊，还有家里老人可能不太喜欢费电的冰箱\u003c/p>\u003cp>店员：这点您可以放心的，这款冰箱采用最近技术，不仅非常省电，而且还很好清理。很多儿女都为父母买了这款冰箱，反馈都很好。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1489135104000,"updated_at":1493189791000,"ria":true},{"id":2011,"topic":"缩小认知差距，做到角色互换","learn_goal":"学完后，能够学会缩小认知差距来消除误解，能够学会角色互换来真","remark":"你是否感觉自己无法说服别人？你是否总觉得无法满足别人的要求？你是否无法揣摩上司的意图？你是否总是找不到被别人拒绝的原因？如果你对上述任何一个问题的回答是肯定的，赶紧加入我们，共同借助《沃顿商学院最受欢迎的谈判课》，缩小认知差距，学会角色互换，提高你的谈判力！","level":"TF3-3","duration":60,"status":0,"type":0,"chaishujia":{"username":"空林文子","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"【书籍介绍】大家好，我是今晚的拆书家林文，今天我要给大家拆解的书籍是《沃顿商学院最受欢迎的谈判课》，这本书是沃顿商学院的教授斯图尔特.戴蒙德的经典著作，其取材源自他在沃顿商学院开的谈判课程，所以其案例都是来源于生活。\r\n事件： 当我们与他人沟通的时候，会出现这样的情况：你滔滔不绝的讲了很久，却发现对方一脸懵，根本就不知道你在讲什么； \r\n更有甚者，我们会觉得对方不可理喻，简直就是对牛弹琴，当其中一方控制不了情绪的时候，冲突就爆发了。\r\n提问： 遇到这样的情况，你以前是怎么处理的？\r\n学习者1：直接发飙。\r\n学习者2：冷战\r\n影响：这些情况如果发生在家里，可能砸下东西就结束了。但是如果在商场上， 不能妥善的缩小双方的认知差距，再加上冲突导致的沟通不畅，往往会造成极为严重的后果，比如失去订单，得罪上司，等等。\r\n解决：《谈判课》里使用大量的真实案例以及归纳总结出理论，让我们能够有效地处理类似的认知偏差情况，做到沟通顺畅，顺利完成既定的目的。","ratings_count":0,"texts":[{"id":4636,"quote":"\u003cp>\u003cstrong>学习目标1\u003c/strong>：学完后，学习者能够学会通过缩小认知差距避免造成冲突\u003c/p>\u003cp>\u003cstrong>【片段一拆解】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong>拆书家：\u003c/strong>在开始拆书之前，我想请大家看下这张图片，请问你看到了什么？\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者1：\u003c/strong>我看到了1个老太太\u003cstrong>。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者2：\u003c/strong>我看到了一个少女。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>好的，谢谢小伙伴的回答。这张图片解释了认知偏差的概念，就是你看到的跟我看到的是不一样的，我们今天的第一个学习目标就是教大家如何缩小认知差距。下面请大家开始阅读片段一，时间2分钟，请在阅读的同时，思考这个问题：为了缩小认知差距，作者给出了哪些建议？\u003c/p>\u003cp>\u003cstrong>片段一：\u003c/strong>\u003cstrong>缩小认知差距\u003c/strong>\u003c/p>\u003cp>我们如何解决沟通失败和观点存在差异这些问题呢？你必须明白的一件事是，这些问题无时不在，无处不在。首先，检查你们双方所说的话，看看双方意思是否一致。\u003c/p>\u003cp>乔斯林·多纳特（JocelynDonat）是摩根大通集团的执行董事，睡觉前，她对两岁的小侄女安娜丽莎说：“现在是乔斯林姑姑讲故事的时间。”她的小侄女立刻就说：“讲两个故事。”几个回合之后，乔斯林最后问小侄女为什么要讲两个故事，小侄女的回答是：“因为我不累。”她们商定好讲一个比较长的故事，但两个人对故事的长短却有着不同的看法。\u003c/p>\u003cp>\u003cstrong>从现在起，当你与某人发生冲突的时候，问问自己下列问题：（1）我的看法是什么？（2）对方的看法是什么？（3）是否存在观点不一致的情况？（4）如果是，原因是什么？\u003c/strong>\u003c/p>\u003cp>大多数人在谈判一开始就摆出各项事实。然而，在这个世界上，大多数人对事实和理性都不感兴趣。在谈判中，我们应该这样开始：对方准备好要听我说话了吗？要想知道答案，你必须了解对方脑海中的画面：他们的观点和感受、对你的看法以及对世界的看法。如果不这样做，你就无从下手，就如同在黑暗中摸索前行。\u003c/p>\u003cp>解释你的观点是你应该做的最后一件事。首先，来了解对方的观点。\u003cstrong>了解对方观点的一个好办法是提问\u003c/strong>。在谈判中，提问要远比陈述更有力量。陈述会让你受制于自己所说的话，无法帮你获取任何信息，而且还会授人以柄，让你成为众矢之的。换句话说，提问不会让你受到限制，通常还会帮你获取信息，如果你愿意还能授你以柄。提问可以让对方将注意力放在他们自己身上。在谈判中，几乎你所说的一切都应该以提问的方式表现出来。这有助于你搞清楚对方是否真的打算把自己的意图告诉你。\u003c/p>\u003cp>\u003cstrong>提问的时候，你不必一脸不快的样子\u003c/strong>。许多人想当然地认为，提问往往会充满敌意。事实上，提问的方式可以各种各样。我最喜欢的一种是有些过时的电视人物神探可伦坡所\u003c/p>\u003cp>使用的策略：“帮帮我吧，我有些迷惑……”这是一种强有力的提问方式——向对方寻求帮助。还有一种合作性的、强有力的提问方式：“请告诉我，我错在哪里。”如果对方告诉你，你就获得了有助于你下一次谈判的信息。再说一遍，谈判结束与否由你说了算。如果对方无法说出你错在哪，那你就会变得更有说服力。\u003c/p>","explains":"\u003cp>拆书家：请小伙伴回答，为了缩小认知差距，作者给出了哪些建议？\u003c/p>\u003cp>学习者1：友善的提问。\u003c/p>\u003cp>学习者2：以让对方帮忙的方式。\u003c/p>\u003cp>拆书家：我总结一下作者给出的建议，当出现认知偏差的时候，首先要问自己四个问题：我的看法，你的看法，你我的看法有没差异，如果有差异是什么原因造成的。其次，向对方提问，注意语气与方式，将自己放在弱势地位，我请求帮助、我错在哪里。千万不要反问：难道不是这样吗？\u003c/p>\u003cp>【使用边界】当我们觉得沟通不畅导致事情不能顺利进展的时候，我们就该考虑是不是有认知差距，然后确定双方的认知存不存在偏差，通过提问确定这个偏差在哪里，然后想办法将其解决。\u003c/p>\u003cp>【不这么做的坏处】如果没有及时沟通，可能会出现疑人偷斧的情况，不断扩大双方的分歧，最终导致巨大的损失。相信在坐的有些小伙伴是处于热恋中的，那请问，如果你发了短信给对象，但是对方没有及时回复你，你会怎么想？\u003c/p>\u003cp>学习者：冷战，不理他，或者分手。\u003c/p>\u003cp>拆书家：这就是一条短信引发的血案。所以，我们一定要及时的去沟通，缩小认知差距。\u003c/p>","interaction":"\u003cp>请大家编写一个剧本，只要几百字就可以了，要设计出人物、情节变化（起因、经过、结果）和当时双方的对话。故事里要体现出如何消除双方的认知差距，时间5分钟，5分钟后请一个小组上来分享你们的剧本。\u003c/p>\u003cp>【学习者剧本演练】\u003c/p>\u003cp>学习者1：我们的背景是这样的，我是商店售货员，我售卖空调，这个空调的报价是2万元。现在有个客户进店来询问空调价格，想要购买，下面我们演练一下我们之间的对话。\u003c/p>\u003cp>客户：请问你这个空调的价格是多少？\u003c/p>\u003cp>店员：2万元。\u003c/p>\u003cp>客户：这么贵，这个空调最多就1万块。\u003c/p>\u003cp>店员：小姐您好，请问你想要的空调需要什么样的功能？\u003c/p>\u003cp>客户：不就是制冷制热吗，还有其他的吗？\u003c/p>\u003cp>店员：好的，那请问，如果有一款空调，可以节省95%的电量，请问你愿意加多少钱？\u003c/p>\u003cp>客户：加3000块。\u003c/p>\u003cp>店员：好的，那请问你，夏天的时候，天气闷热，开了空调半天还不能让你感到凉爽，但是我们这款空调可以让你直接用手机操作将其远程打开，你回家就可以享受清凉了，请问，这么酷炫的功能，你打算花多少钱？\u003c/p>\u003cp>客户：加2000块。\u003c/p>\u003cp>…\u003c/p>\u003cp>店员：好的，你已经加加到23000块了，但是这款空调只需要20000块，你赚到了，请问，这款空调你是刷卡还是现金交易呢？\u003c/p>\u003cp>拆书家：非常感谢两位小伙伴的精彩演绎，他们完美的演绎了认知差距是一步一步的缩小的。从他们的演练中，我不仅看到了提问的使用，同时，店员一步一步的引导，慢慢地减少认知偏差，从而成功售卖空调，给我们的启示就是认知偏差可以通过分步骤来缩小，不一定要一步到位。关于如何缩小认知差距，我们就讲到这里，接下来我们进入片段二。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":4637,"quote":"\u003cp>【\u003cstrong>片段二：角色互换\u003c/strong>】\u003c/p>\u003cp>【A1-问卷调查】阅读片段二之前，请小伙伴花1分钟时间做一下这个小调查\u003c/p>\u003cp>下面有5个题目，请按照1~5分的标准给自己打分，1代表完全不符合，5代表非常符合。这个调查将让你了解自己洞悉他人真正想法的能力。请仔细阅读下面表格中的每句话，根据自己的实际情况为自己打分。做完之后请将分值相加。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1.我喜欢站在对方的角度向其提出恰当要求。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2.我能够预知他人的决定。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3.我喜欢倾听他人发言。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4.我善于向他人提问。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5.我喜欢分析别人的性格特征。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>拆书家：现在我给大家解释一下各分段分别代表着什么。9分以下，不喜欢揣摩他人，更喜欢表述自己。10-18分，分析他人想法的能力很强。 19分以上，你应该经常被别人形容“你就是我肚子里的XX”这个评分可以从某方面反映我们洞悉他人想法的能力，但是世事无绝对，毕竟这个调查比较粗略，只是给大家提供一个参考。接下来请大家花3分钟时间阅读片段二，阅读的时候请思考：什么是角色互换，怎么样才能做到角色互换？\u003c/p>\u003cp>\u003cstrong>【R2：角色互换】\u003c/strong>\u003c/p>\u003cp>角色互换是指把自己置于对方的位置，也叫换位思考或共情。这一技巧能让你更清楚地了解对方的观点、也许正在面临的压力以及他们的梦想和恐惧。换句话说，要想理解对方，就必须尽量去感受他们的痛苦、快乐以及疑惑，并将其纳入你的谈判策略中。而且你还必须让对方知道你正在努力理解他们。\u003c/p>\u003cp>人们往往无法表达自己的感情。你的任务就是找出隐藏在人们言论背后的真正想法。如何才能做到这一点呢？可通过如下方式：\u003cstrong>努力找出有关对方的更多信息、将自己置于对方的位置、努力看清对方脑海中的画面。\u003c/strong>\u003c/p>\u003cp>从对方的角度进行思考往往会带来意想不到的结果。“芭芭拉·特鲁宾是一名正在攻读工商管理硕士学位的医学系学生，她曾在费城一个贫困地区的一家诊所工作。一天，诊所里来了一个看上去饱受虐待的女人，要求做怀孕测试。\u003c/p>\u003cp>经过进一步地询问，芭芭拉发现这个女人：（1）是一名妓女；（2）吸食可卡因上瘾；（3）发生性行为时未采取任何保护措施；（4）经常遭受老鸨的毒打；（5）如果怀孕就无法接客；（6）不知道父亲是谁；（7）如果怀孕就会遭到老鸨更加狠毒的殴打；（8）如果怀孕她想做流产手术；（9）生活贫困；（10）没有接受过良好教育；（11）以前从未去过诊所。\u003c/p>\u003cp>我让全班同学对这一情况进行分析。只有个别学生想到要问这个问题，即这个女人为什么会到诊所里要求做怀孕测试。显然，要想检测是否怀孕，使用家用检测试剂即可。因此，这个女人出现在诊所这一简单事实充分说明她是来求救的，并非为了做怀孕测试。要找出人们说话的真正意图，而不是表面意图，这一点很关键。\u003c/p>\u003cp>芭芭拉为这个女人做了怀孕测试，并对她谈了一些自己的建议，包括在另一个城市找一个过渡性落脚点，以躲开虐待她的老鸨。\u003c/p>\u003cp>即使你是错的，你为了理解对方而付出的努力也会让对方心存感激。\u003c/p>\u003cp>经常将自己置于对方的位置。让你的同事扮演你的角色。参加模拟谈判。你不需要很多花哨的理论，你所需要的只是角色互换的方法、进行角色互换的意愿以及一点点时间。你会因此而成为一名更出色的谈判者。\u003c/p>","explains":"\u003cp>Q1：哪个小伙伴能告诉我，什么叫角色互换？\u003c/p>\u003cp>学习者1：角色互换就是换位思考，共情。\u003c/p>\u003cp>Q2：怎么样做到角色互换？\u003c/p>\u003cp>学习者2：努力找到更多对方的信息。\u003c/p>\u003cp>拆书家：做到角色互换，就是要努力找出有关对方的更多信息、将自己置于对方的位置、努力看清对方脑海中的画面。\u003c/p>\u003cp>【逻辑】换位思考就是要从对方的立场看问题，你不登上泰山，怎么能有“一览众山小”的感觉？抛弃我们自己的观点，寻找到对方的真正需求。\u003c/p>\u003cp>【步骤】：那到底怎么样才能做到角色互换呢？根据作者给出的思路，我们可以总结出以下的操作步骤：1、找出对方更多的信息，这个信息包括了什么呢？兴趣、爱好、习惯、做事的方法、籍贯、性格、脾气。 2、将自己置于对方的位置。这个位置，包括了职位，立场，当时的情绪，顾虑等等。你只需要考虑你能用的上的立场，比如涉及销售，那你只要考虑对方的需求是什么，怎么样让他利益最大化，而不用说去考虑他是一个父亲还是一个儿子。3、努力看清对方脑海中的画面。这是对步骤1跟2的综合应用。我们了解了对方的信息，知道其立场之后，静下心来，在自己脑海中模拟一下他会怎么想。你可以找人跟你一起情景演练，让这一过程更加符合实际情况。\u003c/p>","interaction":"\u003cp>【A3微行动】大家在日常生活中，有没碰到特别棘手的问题想解决的，给大家分享一下，看看能不能用今天学习到的知识将其解决。\u003c/p>\u003cp>学习者：我的弟弟念大学，读大三不想继续读，退学了，现在在家无所事事，前天听妈妈说他夜不归宿，我就跟我弟打了电话，沟通过程很痛苦，他很长时间沉默，或者回答不知道。我就生气了，说我也懒得管你了，啪！把电话挂了。我不知道该怎么样沟通才能帮到他。\u003c/p>\u003cp>拆书家：你的问题是你想与他沟通，但是他就是沉默，根本不想跟你交流，让你无计可施，对吗？\u003c/p>\u003cp>学习者：对的。\u003c/p>\u003cp>拆书家：好的。这位小伙伴目前遇到的问题是弟弟自己退学在家，不想与人沟通，对于这样的情况，请各小组针进行讨论，看看能不能想出一个解决办法，可以让他愿意沟通，从而让我们能帮到他。5分钟之后请大家分享你们小组讨论的结果，看看大家能不能想出一个解决的办法。\u003c/p>\u003cp>分享1：我们小组讨论出来的方法是首先要放下控制，因为你问他的问题，可能他自己也不知道答案，如果这个时候我们再控制、要求他，他反而更不愿意告诉我们。其次是陪伴，了解他感兴趣的是什么。第三，直接收集他的信息，这个收集的渠道是多方面的，他的老师同学等。\u003c/p>\u003cp>拆书家：其他小伙伴有没补充的？\u003c/p>\u003cp>分享2：我们的讨论结果是，首先是了解事实，我们要知道到底发生了什么事情。其次是理解感受，我们做家人的要知道他目前的真实感受，不能批评他。第三，共同探讨解决，与他一起去寻求解决问题的办法。\u003c/p>\u003cp>拆书家：非常感谢两个小伙伴份分享。我总结一下他们讨论出的解决方案：首先是要放下控制，了解事实的真相。其次，给他陪伴，理解他的真实感受 。最后，收集他的信息，并且与他共同探讨解决问题的办法。\u003c/p>\u003cp>【A1-学习者分享】\u003c/p>\u003cp>学习者：刚才听这位小伙伴分享的方法，我想起来一个发生在我哥身上的事情。我哥的小孩上小学，前阵子老师批评他上课老迟到。我哥很生气，但是他没有直接跟他发火，他问他到底为什么会迟到呢。小家伙告诉我哥，其他同学都是头天晚上没做完作业，所以要早点去学校抄作业，但是我作业做完了，所以不用那么早去学校抄作业，就容易迟到了。我哥跟我说，幸亏了解了事实的真相，不然真不知道会造成什么样的后果。\u003c/p>\u003cp>【A3-促动参与】\u003c/p>\u003cp>你在公司里面兢兢业业地努力工作，但是领导就是不能给你升职加薪，你觉得非常苦恼。于是你找到你的朋友，向他诉苦。你的朋友一步一步的引导你，找到自己不被领导升职加薪的真正原因。大家花10分钟时间，在小组内讨论，然后我们会请一个小组上来进行角色扮演，两个角色，其中一个是苦恼的上班族，另外一个帮他解决问题的朋友，看看你们是如何引导来了解领导的真正需求，从而达到角色互换的目的。\u003c/p>\u003cp>拆书家：下面请一个小组上来分享你们的讨论结果。\u003c/p>\u003cp>热心的朋友：我负责引导我的朋友去了解领导真正的需求。下面我们开始。\u003c/p>\u003cp>苦恼的上班族：姐，你说我都进公司三年了，老板一直不提加薪的事情，跟我一起进来的人都加薪了。\u003c/p>\u003cp>热心的朋友：你有没了解过他们是怎么加薪的？\u003c/p>\u003cp>苦恼的上班族：我也没发现他们能力有什么特别的，工作效率还不如我呢。\u003c/p>\u003cp>朋友：那你有没跟以前加薪的同事聊过呢？\u003c/p>\u003cp>上班族：没有呢。\u003c/p>\u003cp>热心的朋友：那他们加薪了， 你没加薪了，那肯定是他们在上班的过程中做了一些你没做的动作。你有没了解过老板的加薪标准？\u003c/p>\u003cp>苦恼的上班族：没有呢。\u003c/p>\u003cp>热心的朋友：这里有一个工具，我帮你一起分析一下到底你们老板是怎么样的。你看，这个图中显示了一般华人圈领导的用人标准，这样组合起来有8个标准，忠诚、亲近、有才，叛逆、疏远、平庸，等等组合。你觉得你的老板的用人标准是什么，通过这个你可以判断你为什么还没有得到升职加薪？\u003c/p>\u003cp>上班族：我老板是外国人，他比较喜欢忠诚的员工。但是我们中国这边的主管喜欢给那些他直接招进来的人升职加薪，比如他的亲戚啊，朋友啊。\u003c/p>\u003cp>热心的朋友：这样啊，你的主管比较喜欢任人唯亲啊。那你知道现在你该怎么做了吗？\u003c/p>\u003cp>苦恼的上班族：我想我应该换工作了。\u003c/p>\u003cp>拆书家：非常感谢这两位小伙伴的分享。这个工作非常强大，可以帮助我们了解领导的真实用人标准。但是最后这个小伙伴直接选择换工作，我觉得这个亲疏其实是可以改变的，所以如果考虑怎么跟领导走的更亲近，或许能让你也得到升职加薪。\u003c/p>\u003cp>【A2-催化应用】学完了角色互换，大家肯定跃跃欲试。大家手边都有便签纸，请大家花3分钟的时间，在纸上写下你对某个人的分析，可以是你的同事、领导、配偶、朋友，通过分析之后，你会做出什么样的行动，来让其高兴或者答应你的某个要求。\u003c/p>\u003cp>拆书家：请一个小伙伴来分享一下你的分析对象，以及你打算如何做一件让他高兴的事情或者让他答应你的某个要求。\u003c/p>\u003cp>学习者：我分析的是我的舍友。她是一个特别希望得到他人认可她所做的事情的人。我17年的计划是想成为一个拆书家，但是我不想一个人去，于是我想怂恿她一起来。于是我打算这样跟她说：你了解拆书帮是怎么样的团体吗？我2017年想成为拆书家。我想如果你也去，你可能能更容易的成为一个拆书家。\u003c/p>\u003cp>【总结】今天我们主要学习了两个片段，第一个片段是通过提问的方式来缩小认知差距，第二个片段是教大家学会角色互换。这两个片段有递进的关系，如果你能做到角色互换，那认知差距是可以缩小的非常小的。所以，今天我们是教大家去通过缩小认知差距来避免冲突。我相信，今天的学习能够让大家在以后的沟通中，更少的受到认知差距的影响，让我们的沟通更顺畅。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":true}}],"created_at":1487606565000,"updated_at":1487606565000,"ria":true},{"id":2006,"topic":"原则，一种无法辩驳的力量","learn_goal":"学会使用原则来达成自己的谈话目标","remark":"善于在谈话中利用原则的力量，能让我们事半功倍地达成我们的目的。什么是原则，怎么样发现原则，怎么样使用原则为我们所用？掌握了这几个技能，你将Getting More.","level":"TF2-3","duration":25,"status":0,"type":0,"chaishujia":{"username":"空林文子","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"【图书介绍】\r\n这本《谈判课》的作者是美国的斯图尔特.戴蒙德，他是世界级的谈判专家，在沃顿商学院教授谈判课，他的课程在沃顿商学院的地位正如这本书的名称一样，是实至名归的。这本书是作者以其自己课程为基础，整理出的一整套极其有效、适用于任何人和任何情境的谈判技巧：孩子和工作、旅行和购物、商场、政坛、人际关系、文化差异、爱人和伴侣、竞争对手等。 \r\n当当网中，对于这本书的评论有5W条，好评率99.5%。由此可见其销量与如潮的好评。前几天开车听广播，我还听到广播里在推荐这本书，当时我有种找到知音的感觉，因为一直以来我都非常喜欢这本书，但是我不知道原来还有这么多人也喜欢。这些足见这本书，确实是有口皆碑的。为什么如此备受推崇呢？\r\n这本书的英文名叫《Getting more》，这也是本书的一条原则：任何人都能争取更多。争取更多的什么呢？看看我的案例。\r\n(引发悬念)上周六我去仙湖植物园，看到入口处的汽车排了一条长龙，于是到旁边小区停车，但是前面那辆车被保安拒绝了，我想着如果要换地方，肯定得花很多时间，于是我开过去，仔细观察，里面有商铺，我计上心来，对保安说：我要去那家理疗店。保安很疑惑的","ratings_count":0,"texts":[{"id":4630,"quote":"\u003cp>一天晚上，我的一个学生在10点55分去麦当劳买份法式炸薯条。薯条有些湿软，他要求柜台服务员换一份新鲜薯条。服务员不耐烦地回答说：“再过五分钟我们就关门了！”这名学生平静地走到柜台另一端，拿起一张麦当劳印制的保证食物新鲜的宣传单，然后走回到服务员那里。\u003c/p>\u003cp>“我现在在麦当劳，对吗？”这名学生说。店员嗯了一声。“那好，”学生说，“这张宣传单上面说你们的食物在整个营业期间都是绝对新鲜的。”他指着宣传单上法式炸薯条一栏，上面承诺会带给顾客所期望的“完美品质”。“这家店难道不是要到晚上11点才停止营业吗？”这名学生补充道，“宣传单这一栏并没有写保证食物新鲜在停止营业前5分钟就开始失效，对吗？”这名学生买到新鲜的法式炸薯条了吗？他当然买到了。\u003c/p>\u003cp>很多人会无奈地接受湿软的薯条，或一气之下转身离开，或气愤地与店方发生争执，或气恼不堪。这名学生的做法却是冷静地利用了麦当劳为自己制定的准则。毫无疑问，这是一件小事，但在成千上万的谈判中，无论大小，从餐馆到你的工作，再到地缘政治，利用对方的准则是一种有助于你实现目标的极具说服力的方法。\u003c/p>\u003cp>在大多数人都不甚了解的众多极其有效的谈判技巧当中，利用对方的准则也是其中之一。这种技巧对那些难对付的谈判者尤为有效。然而，很少有人了解这个准则，对它加以利用的人就更少，几乎没人明白准则是能使人们在各种情况下应对自如的心理杠杆。我不是在谈论“客观”准则或你认为公平的准则，而是被对方认为公平合理的准则。\u003c/p>\u003cp>准则一旦利用起来，通常会产生神奇的作用。每天你都可以使用这种技巧，在有些情况下这种技巧尤为有效。\u003c/p>\u003cp>利用对方的准则非常重要，因为这个世界本来就是不公平的。不断有人和公司违反自己制定的准则。他们对服务作出承诺，又违反承诺。从商店订购商品，但商品却未按承诺交付。他们承诺要提供最优质的服务，但服务态度却异常恶劣。你信任他们所作出的承诺，而他们却通常理直气壮地食言背信。这种现状让很多人十分抓狂。但现在，你可以从容镇定地利用他们的准则来达到你的目的。\u003c/p>\u003cp>蒂姆·拉瑟特（TimRussert）是美国全国广播公司（NBC）电视节目《与媒体见面》（MeetthePress）的主持人，经常因精彩出色的报道而备受称赞。在采访美国政要的时候，拉瑟特经常会做的事情之一是，在国家电视台上将这些政要们以前所说的话重新播放给他们听，而这些话似乎与他们当前的行为相互矛盾。政要们会局促不安，然后被迫自圆其说。拉瑟特正是利用了对方的准则。\u003c/p>\u003cp>早在三十多年前当记者的时候，我就发现利用对方的准则效果惊人。后来当律师和商人的时候，我对这一技巧进行了完善。现在，这一技巧已经成了我的课堂上诸多谈判技巧中的一个重要组成部分。\u003c/p>\u003cp>这一技巧如何发挥作用呢？利用对方的准则是人类心理学的一个基本原则，即人们讨厌自相矛盾。所以，如果你让人们在这两者之间进行选择：是和自己的准则相互矛盾，还是和自己的准则保持一致——例如和自己以前所说的话和所作的承诺保持一致？人们通常都会力争和自己的准则保持一致。当然，任何技巧都不可能始终有效。但是，通过运用这些技巧，你会争取更多。人们违背自己准则的可能性越低，你达到自己目的的可能性就越高。\u003c/p>\u003cp>准则是赋予某项决定合理性的一条惯例、一项政策或一个参照点。它既可以是从前所说的话、所作的承诺或所给予的保证，也可以是谈判中对方同意采取的一种做法。\u003c/p>","explains":"\u003cp>好，大家看完了，现在应该知道我在向保安提出要求的时候运用了什么技巧吧。对，就是今天我们要讲的准则的力量。我利用了保安对于自身工作的定位：保护小区业主的权益。商铺开在小区里面，当然也是小区的一部分，他不可能替商铺将顾客拒之门外吧。所以，以后有车的小伙伴可以充分的利用这一个经验。\u003c/p>\u003cp>原文中对于说话中利用的准则有过一些定义，我不是在谈论“客观”准则或你认为公平的准则，而是被对方认为公平合理的准则。\u003c/p>\u003cp>准则包括什么：它是赋予某项决定合理性的一条惯例、一项政策或一个参照点。它既可以是从前所说的话、所作的承诺或所给予的保证，也可以是谈判中对方同意采取的一种做法。\u003c/p>\u003cp>【HOW】怎么使用准则来Getting More呢？我们根据书中的案例来分析一下：首先：他跟对方确认这是在麦当劳。从这里，我们可以得出一个简单的步骤，跟对方确认所处的场景，这是为了后面引出准则做准备。其次：他使用宣传单上关于食物在营业期间都是绝对新鲜，他使用的准则是对他使用的准则是对方所作的承诺。如果没有宣传单这种东西，那我们可以观察下周围有没有类似“为人民服务”“客户是上帝”这样类似的标志。虽然这些东西都是挂在口头上的，但是如果能在现场找到类似的标语，效果将完全不同。就像是在犯罪现场找证据一样。第二步，环顾四周找证据，没有证据怎么办？找出对方能够在谈话中接受的准则，或者直接问对方的准则。第三步，说出对方应该怎么做才是符合这个准则的。\u003c/p>\u003cp>但是大家要注意，在运用原则的时候，首先一定要心平气和，让对方乐于接受，不能让对方以为你是在用准则压他，那样可能会得不偿失。\u003c/p>\u003cp>其次，千万不要在大庭广众之下使用，否则你会被拒绝的很惨。\u003c/p>\u003cp>最后，不要滥用，因为如果用这个得到的利益，可能会让你良心不安，那就不合适了。\u003c/p>\u003cp>这里有一个案例，如果我们在取款机被吞卡，银行工作人员肯定不会来；但是如果我们报警说取款机多吐钱了，他们肯定马上到场。这里用了什么准则呢？这里使用了，银行就是为人民币服务。你伤害到了他的利益，肯定就出来了。这条准则希望大家以后能运用到生活中，肯定有奇效。\u003c/p>","interaction":"\u003cp>\u003cstrong>【促动学习者现场演练（A3）】\u003c/strong>\u003c/p>\u003cp>假设你在美团团购了200的代金券，然后你去餐馆消费，消费完之后餐馆拒不给你开发票。你如何使用准则的力量让餐馆将发票给你？\u003c/p>\u003cp>\u003cstrong>学习者现场演练：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者1-消费者\u003c/strong>：老板，请你按照消费额度给我开具发票。\u003c/p>\u003cp>\u003cstrong>学习者2-老板\u003c/strong>：我们这家店开门做生意这么久，就从来没有开过发票。\u003c/p>\u003cp>\u003cstrong>学习者1-消费者\u003c/strong>：你们这样是不对的，根据税务法及工商局的规定，你们必须要开具发票。\u003c/p>\u003cp>\u003cstrong>学习者2-老板\u003c/strong>：我刚才已经给你打折了啊，就不要发票了吧。\u003c/p>\u003cp>\u003cstrong>学习者1-消费者\u003c/strong>：这样不行，我为公司办事，要发票报销，如果你不给发票，我可以去工商局告你，我也可以让我律师来找你，你因为不给发票，后面还会有一大串的麻烦事，所以你还是给我开发票的好。\u003c/p>\u003cp>\u003cstrong>学习者2-老板\u003c/strong>：我再给你打个折不行吗？\u003c/p>\u003cp>\u003cstrong>学习者1-消费者\u003c/strong>：不行，我就要发票。\u003c/p>\u003cp>\u003cstrong>学习者2-老板\u003c/strong>：好吧，我个你开。\u003c/p>\u003cp>\u003cstrong>【拆书家总结】\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 看来大家已经学会使用准则的力量来为自己争取权益了，下面我给大家补充一个实用的准则。大家都喜欢在淘宝购物，如果你在淘宝购物了，他在7天内降价，要全额个你补差价，如果是半个月内，那他要补你一半的差价。充分的利用准则的力量，为自己争取更大权益吧。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1487604609000,"updated_at":1487604609000,"ria":true},{"id":1647,"topic":"谈判","learn_goal":"以小搏大的谈判","remark":"本书的作者是斯图尔特•戴蒙德教授，他曾为谷歌、微软、保诚、摩根大通等财500强中企业提供过咨询服务，他所讲授的的谈判课，连续13年都是沃顿商学院最抢手的课程.作者通过对3万多人的谈判案例进行研究，加上40余年来在自己职业生涯中的体验和感悟，总结出了一套具体详细、实践性强、效果更好的谈判技巧。","level":"TF2-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"娘娘","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"大家好，我是拆书帮翰林分舵的拆书家席梦婷，拆书帮的小伙伴都叫我娘娘，今天我带给大家的片段节选自《沃顿商学院最受欢迎的谈判课》。\r\nF：本书的作者是斯图尔特•戴蒙德教授，他曾为谷歌、微软、保诚、摩根大通等财500强中企业提供过咨询服务，他所讲授的的谈判课，连续13年都是沃顿商学院最抢手的课程.作者通过对3万多人的谈判案例进行研究，加上40余年来在自己职业生涯中的体验和感悟，总结出了一套具体详细、实践性强、效果更好的谈判技巧。\r\nA：在本书中，你会发现太多对传统观点的挑战。比如谈判中大家都想达到的“双赢”，本书会告诉你，很多时候与“双赢”相比，以今天的失利换取明天更大的利益要更加明智。作者认为：并非一切谈判都以金钱为核心，各种无形之物，如尊重对方，往往会令你获得更为丰厚的回报。\r\nB：本书以戴蒙德教授的课程为基础，介绍了一整套极其有效、适用于任何人和任何情境的谈判技巧，无论是孩子和工作、旅行和购物、商场、政坛、人际关系、文化差异、爱人和伴侣、竞争对手，都可以运用书中的技巧和他们去沟通。本书的目的不是教你学会谈判，而是要让你从内心深处成为一名真正的谈判者，让这些谈判技巧和策略就像你的性格一样","ratings_count":0,"texts":[{"id":4203,"quote":"\u003cp>几年前，造纸行业的一位主管告诉我，有一笔价值达数百万美元的交易他怎么都无法达成协议。\u003c/p>\u003cp>“我们对这笔交易和客户反复思索，想搞清楚对方究竟想要什么。”这位名叫拉里• 斯蒂尔曼的主管说，他现在是犹他州的一名企业家，“最后我们终于搞清楚了，原来对方想要4张篮球赛门票。”虽然只是几张NBA决赛的门票，但它却成了解决问题的关键。\u003c/p>\u003cp>对该客户而言，他只是想通过这种方式证实：卖方会不惜一切代价让其客户满意。最后，拉里的公司得到了那份价值数百万美元的纸张供应合同。\u003c/p>\u003cp>那一天，拉里发现了一种技巧，这一技巧几乎无人使用，完全明白这一技巧并能自觉坚持成功地对其加以运用的人更廖廖无几。这个技巧就是利用价值不等之物进行交易。谈判各方衡量价值的方式各不相同，对价值大小所持看法往往也不同。一旦找出那些各方对其价值大小持不同看法的东西，就可以利用其进行交易。在这个过程中，你会得到你认为对你有价值的东西，作为交换，你可以放弃对自己而言价值相对较小的东西。\u003c/p>\u003cp>在谈判中，利用价值不等之物进行交易会使谈判项目的总体数量或价值增加，让双方获得更多。对方对价格的敏感度将会降低，双方关系将更融洽，信任度将会提高，你自己对对方的价值也将增加一一无论在事业上还是个人生活中。\u003c/p>","explains":"\u003cp>古希腊数学家阿基米德说过：“给我一个支点，我能撬起整个地球。”这句话也适用在谈判中。原文给我们介绍了一个谈判的技巧——不等价交易。这种做法的关键是找出对一方价值不大但对另一方很有价值的东西，这个东西相当于支点，然后，利用这些东西进行交易，撬动价值远远超过这个东西的交易。比如原文中的例子，用4张NBA决赛门票换来了几百万美元的订单。\u003c/p>\u003cp>大家可能会觉得，这个方法是挺好，但应用范围很有限啊，我们又不是搞谈判的。但其实无论在生活还是工作中，我们经常会面临谈判，很多沟通的过程就是谈判的过程。比如员工向老板要支持资源，你向同事、朋友求助，买东西讨价还价，追求女生、教育孩子等等，都是谈判的过程。\u003c/p>\u003cp>讲一个特别接地气的例子。\u003c/p>\u003cp>我家附近有个菜市场，里面很多卖菜的摊位，其中有个兄弟俩的摊位，生意特别好，总是一堆人围着，旁边的摊位很少围这么多人。我奇怪这兄弟俩的生意怎么这么好，就仔细观察了一下。我发现这兄弟俩特别会说话办事儿，遇到老人来买菜，比如我妈，一口一个阿姨叫得特别亲切，而且每次都把几毛的零钱抹掉，还给你袋子里再塞一把香菜或者葱之类，我妈买得多了还会送一捆青菜，所以老人特别喜欢去他家买菜。而对我这样的，他们老远就招呼我的孩子，夸孩子穿得真帅，孩子一答话他们就夸孩子聪明，然后会跟我说带孩子特别辛苦，说我能辞去工作真是不容易之类，说得我也特别舒服。所以，我也愿意去他家买菜。\u003c/p>\u003cp>大家看，他们用几根香菜、几句好话换回了这么多的回头客，是不是不等价交易的典型做法？所以，处处是谈判啊。\u003c/p>","interaction":"\u003cp>下面又到了大家的时间。（10分钟左右）\u003c/p>\u003cp>刚才咱们说过，这个技巧可以用在很多场景中，请大家想想，跟老板要人手、要预算，向同事寻求工作上的帮助，想让爱人陪你做一件TA不是特别感兴趣的事儿，督促孩子按时上床睡觉……这么多情景，你涉及到哪个？\u003c/p>\u003cp>请大家根据自己选定的情景，加工一个谈判案例，用到我们今天所学的“不等价交易”这一知识点。（5分钟小组讨论，5分钟分享）\u003c/p>\u003cp>\u003cstrong>学习者1：\u003c/strong>\u003c/p>\u003cp>我在公司和同事的关系都不错，但一些职能部门比如行政人力资源等，平时不怎么接触，等需要的时候去找他们，往往会碰壁：要么事情办不好，要么会拖很久。我决定以后出差，回来不仅给本组的同事带小礼物，也给相关职能部门的同事带礼物。他们也不是真要什么贵重的东西，就是大家多接触，熟悉了应该就好办事了。\u003c/p>\u003cp>\u003cstrong>学习者2：\u003c/strong>\u003c/p>\u003cp>我是做理财业务的，有个客户一直搞不定，对方不接我电话，更谈不上见面。我一直找不到突破口。今天的拆书讲以小搏大，我想到他是60年代生人，会比较怀旧，我知道他的生日，我又会设计。我准备去查查他出生那天的各种报纸，把好的消息都摘出来，设计成一份报纸的样子，再做旧，打印出了寄给他。\u003c/p>\u003cp>（拆书家补：这位小伙伴后来真的这么做了，那个客户收到礼物后立刻打电话约见了他）\u003c/p>\u003cp>\u003cstrong>结语：\u003c/strong>中国有句古话：彼之砒霜吾之蜜糖，意思是一样东西对不同的人来说有不一样的价值，对于我来说可能是蜜糖，是很好的东西。但是对他来说有可能是毒药。应用“不等价交易”其实就是找到那个对别人来说是蜜糖对你来说无所谓的东西，然后交换。希望我今天的分享对大家有所帮助，谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1482223538000,"updated_at":1482223538000,"ria":true},{"id":1300,"topic":"如何使谈判最有效","learn_goal":"顺利通过1-1","remark":"在谈判过程中，权威的第三方能够给对方施压或者提供参考意见，从而顺利达成谈判结果。第三方可以是一个法律法规、也可以是对方尊重的个人或者行业知名公司，甚至是竞争对手。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"撒冷牧童","city":"西安"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"一、自我介绍\r\n大家好，我叫李忠阳，读书、写作是我从小以来的爱好，身边的朋友常说我解决问题的能力很强，我知道这都得益于将知识转化为行动的能力，当我第一次读到《这样读书就够了》这本书时便产生了英雄所见略同之感。帮助别人实现自己的梦想是我最快乐的事情，所以我于2015年发起了西安带路企管管理咨询公司，盼望能在知识管理和应用这条路上能结识并帮助更多的人！\r\n二、拆书帮介绍\r\n “拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心，而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。 \r\n 拆书分为个人学习的拆书法和组织学习的拆书法：个人学习的应用就是便签法；组织学习的应用就是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。\r\n 在拆书学习活动中，拆书家不是权威，权威是拆书家所选的图书，拆书家扮演的是引导者、促动师、催化师的角色，启发、引导学习者进行更深入的思考，促进学习者把知识转化为行动，践行“知行合一”。在拆书帮内部有一本人人必读的书——《这样读书就够了》，目前已经被韩国引进","ratings_count":0,"texts":[{"id":3700,"quote":"\u003cp>《沃顿商学院最受欢迎的谈判课》片段六\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp;几乎在任何一场谈判中都至少会有三个人——即使有时只有两个人在场。第三个人或者第三方通常指的就是这样的人，无论是真实存在或想象中的，即谈判者认为自己必须以某种方式遵从的人。这些人也许是鬼魂和过去的精灵，也许是谈判者告之以谈判的对象——配偶、同事、朋友，在这些人面前，谈判者需要保全面子。他也有可能是老板。问题的关键是，要想实现你的目标并获得更多，你必须对这人负责。\u003c/strong>\u003c/p>","explains":"\u003cp>\u003cstrong>人生处处都需要谈判，\u003cstrong>在谈判过程中，\u003c/strong>即使有时只有两个人在场的情况下，也需要一个权威的第三方，权威的第三方能够给对方施压或者提供参考意见，从而顺利达成谈判结果。第三方可以是一个法律法规、也可以是对方尊重的个人或者行业知名公司，甚至是竞争对手\u003c/strong>。\u003c/p>","interaction":"\u003cp>\u003cstrong>分享\u003c/strong>\u003cstrong>&nbsp;A1&nbsp;\u003c/strong>\u003cstrong>便签\u003c/strong>&nbsp;&nbsp;（A1便签要写出具体的事件，有时间、人物、起因后果）\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp;两年前买车，我喜欢的菲亚特在西安只有两家4S店，因为竞争较少，价格都比较强硬。分别谈的时候，作用都不明显，有一天不小心把给浐灞那家销售员的谈判短信发给了三桥店的销售了。我还挺尴尬，没想到接下来三桥店的态度还挺好，我突然开窍了，把谈判结果告诉浐灞店说另一家优惠了一万多。我都准备下订单的时候，浐灞销售又打过电话来说他们为了清库存也请示上级决定给我一个更大的优惠，最终我以优惠指导价2万2千元的价格开回了爱菲（菲亚特菲翔）。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享\u003c/strong>\u003cstrong>&nbsp;A2&nbsp;\u003c/strong>\u003cstrong>便签\u003c/strong>&nbsp;&nbsp;（A2便签要求有具体的做法，尽量设定具体可衡量的或可观测的行动目标）\u003c/p>\u003cp>\u003cstrong>找出一个在\u003c/strong>\u003cstrong>对方心里有权威或者有压力的第三方对谈判结果非常重要，公司三个月内打算引入一些股权和债券投资以帮助项目的拓展。对融资方的谈判需要用到第三方的理论：\u003c/strong>\u003cstrong>1、我本月会引入两到三位投资人，各自比例都比较小，在谈判过程既可以给彼此带来紧迫感，在公司经营过程中也可以相互制衡；\u003c/strong>\u003cstrong>2、这周末要完成融资计划书，在融资计划书的撰写过程中需要引入第三方的专业意见，包括智库专家和财务方面的专业人才，他们的意见或数据会在计划书标明出来，以此增强谈判公信力。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1479107967000,"updated_at":1479108090000,"ria":true},{"id":350,"topic":"面试初体验","learn_goal":"各方面了解面试公司","remark":"面试学问多，除了与面试官，留意身边的方方面面都是对新公司的进一步了解","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"卢珊","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"大家好，我叫卢珊，一直从事人力资源培训工作，目前处于“失业”中，有需要的伙伴请把我带走。今天是第一次来到光谷练武场，也是我的第一次拆书，高兴中又有点小紧张，在此先谢谢各位大侠。\r\n拆书介绍：温故而知新，让我们再来回想下拆书是什么？拆书就是字面意思的手撕书本？当然没有这么简单粗暴，拆书这种读书方法源于赵周老师的一本书《这样读书就够了》，简单来说就是我们时常听到的RIA便签读书法。那RIA分别是什么呢？R是reading阅读原文片段，I是interpretation用自己的语言重述知识点，A是appropriation，分为A1描述自己的相关经验和A2以后我怎么应用,这个过程的重点是把书本知识转化为自己的应用。\r\n拆书帮介绍：那以这样一种读书方法为核心，吸引了在座每位伙伴而形成的这个集体就叫拆书帮，它更像是一种社群，聚集了来自不同行业不同岗位爱好读书的朋友，那我们所在的是武汉拆书帮的珞珈分舵，除了我们今天所在的光谷练武场外，还有街道口练武场，也欢迎大家每周三来参加街道口的读书活动。","ratings_count":0,"texts":[{"id":896,"quote":"那简单介绍后就让我们一起进入今天我所带来的RIA。这个片段来自于《沃顿商学院最受欢迎的谈判课》一书，请大家用30秒的时间浏览两张图片的内容，浏览完的伙伴请给我一个爱的眼神。\r\n片段：离职者。在这一类人当中，许多人曾目睹过公司最糟糕的一面。他们知道公司无法满足员工们的哪些需求。对他们所说的话，你也许要持保留意见，因为他们说这些话时有可能心情不好，或者有不为人知的冬季。不过你通常都会从中得到一些最真实的信息。如果你正在找工作，而他们是在皆大欢喜的情况下离开公司的，他们也许会打电话把你推荐给公司。\r\n行政人员。他们也被成为长期员工。管理人员和经理常常会换来换去，可很多行政人员却为了事业发展长期留守公司。他们既可以制造流言蜚语，也可以进行积极正面的宣传。将他们拉入你的团队，逢年过节给他们带些小点心。\r\n人力资源部门的人。人力资源部门的人通常最容易对别人说“不”，其主要职责是保护公司。但他们也并非铁板一块。多和他们交朋友，先从职位较低的人开始。对他们的工作表现出兴趣，他们会高兴地向你解释他们的工作。通常，一说起认识和个人问题，他们总会滔滔不绝。","explains":"文中的案例讲述了一个在职场上打拼的工作者，她在三年的时间里与公司各个部门的人进行了一场潜在的谈判，而最终谈判成功证明了自己的价值，也保住了自己的工作。在图片中，我摘抄了一部分大家都会接触到的岗位人员，分别为离职者，行政和人资部门的人员，描述了与他们打交道，进而能得到你所需要的信息，其实简单来说就是我们经常所提到的人际交往。","interaction":"A1：那目前我正在找工作，我给大家带来的经历并不是我曾经在工作中如何与各部门同事打交道，而是我在求职的过程中一些感触。以往求职的过程中，我的了解渠道很单一，在上一次找工作大前年2013年的时候，因为我想做企业内的培训工作，我在前程无忧上确定了一家公司的岗位，那在准备面试之前，我自然要去了解这家公司，那我怎么做的呢，简单粗暴百度，找到这家公司的官网，从头看到尾，信息量之大仿佛让我在眼前就对这家公司有了各种丰富的画面。然而上班之后，自己身在其中，我突然发现当初对于这家公司的了解太表面了，网页上黑白的字体和经过PS的图片其实无法表达公司真正的文化氛围，也导致在有一段时间内我心里稍微有些小小的失望。那反思来说是我的了解渠道太多单一，信息刻板而无人内心的真实感受，也许这对于求职来说并非都是最大的影响因素，但依然会在工作中波动你的心弦。\r\nA2：那在接下来的求职过程中，除了我以往所关注的公司官网、前程无忧等招聘网站的介绍，我想应用文中这三个岗位的人员来对未来东家增加一些了解。\r\n首先是离职者，当然前提是我认识离职者，那在人资和培训的行业内交流是非常多的，会有离职人员介绍我去公司面试的情况，那我就可以与离职人员进行有目的的聊天。他所能给我带来的更多的可能是公司的负面信息，那这个信息就需要我去客观的看待，同时也要思考他所离职的原因是否也会成为我未来工作前进的难题，而这个问题是否大到影响我去这家公司工作。\r\n其次是行政人员，我所能接触的一定是公司的前台，我可以提前到达面试公司与她做个三两句的交流，她守护着公司的入口，无论是公司的人来人往或是流言蜚语，她心里一定会有个小本子记着，那作为培训工作者，我可能首先要了解的就是每天来面试的人多吗，或者每月离职的人多吗；其次就是前台的待人接待的态度往往也能体现一家公司的人文文化，她是热情的还是急促的，亦或是一板一眼的。\r\n那最后就是面试过程中一定会碰到的人资面试官，他所描述的公司信息一定是全面而又积极的，我更能了解到那些官网上感受不到的公司文化和发展前景。\r\n那在面试后我会将这三者所给我带来的信息进行综合，起码就对新公司有了更深入的了解。其实以往我们在面试的过程中也会有这样不经意的举动，但我想下一次面试的时候，我想把这个举动变为有目的的行动，从而帮助我去做选择。","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1463748762000,"updated_at":1463748789000,"ria":true}]};